window.PDD_DATA = window.PDD_DATA || [];
window.PDD_DATA = window.PDD_DATA.concat([{"num": 442, "text": "В общем, если две полосы движения предусмотрены на подъезде к кольцевой развязке, какую полосу следует занять водителю, если он намерен повернуть направо (позиция на 12 часов) от кольцевой развязки?", "topic": "Перехрестя та кільцеві розв'язки", "options": ["Ехать по обеим полосам.", "Левую полосу.", "Любую полосу.", "Правую полосу."], "correct": 3, "expl": "Якщо на в'їзді до кільцевої розв'язки є дві смуги, і водій має намір виїхати праворуч (позиція на 12 годині чи далі), йому слід зайняти праву смугу.", "explSpecific": "Правильно — «Правую полосу». Ліва смуга, будь-яка смуга чи рух обома смугами одночасно не відповідають правилу зайняття смуги для виїзду в правому напрямку розв'язки."}, {"num": 443, "text": "Какую позицию должен занять водитель при приближении к кольцевой развязке, когда намеревается сделать первый съезд налево?", "topic": "Перехрестя та кільцеві розв'язки", "options": ["Подъехать по правой полосе.", "Подъехать по левой полосе.", "Подъехать по обеим полосам.", "Подъехать по любой доступной полосе."], "correct": 1, "expl": "Якщо водій має намір здійснити перший виїзд ліворуч на кільцевій розв'язці, йому слід заздалегідь зайняти ліву смугу при наближенні.", "explSpecific": "Правильно — «Подъехать по левой полосе». Права смуга, обидві смуги чи будь-яка доступна смуга не відповідають правилу зайняття смуги для першого (найближчого) виїзду."}, {"num": 444, "text": "Что должен знать водитель перед въездом на кольцевую?", "topic": "Перехрестя та кільцеві розв'язки", "options": ["Транспорт спереди- как быстро он движется и насколько близко он находится.", "Транспорт справа - как быстро он движется и насколько близко он находится.", "Транспорт слева- как быстро он движется и насколько близко он находится.", "Транспорт сзади- как быстро он движется и насколько близко он находится."], "correct": 1, "expl": "Перед в'їздом на кільцеву розв'язку водій повинен насамперед оцінити транспорт, що наближається справа, — його швидкість і відстань до нього, оскільки саме він має перевагу проїзду.", "explSpecific": "Правильно — «Транспорт справа - как быстро он движется и насколько близко он находится». Транспорт спереду, зліва чи ззаду не має вирішального значення для визначення пріоритету при в'їзді на кільцеву розв'язку."}, {"num": 445, "text": "В общем, при повороте направо на дороге с двусторонним движением, где водитель должен расположить транспортное средство?", "topic": "Загальні правила та поведінка на дорозі", "options": ["По обе стороны от середины дороги.", "Слева от середины дороги.", "На крайней правой стороне дороги.", "На крайней левой стороне дороги."], "correct": 1, "expl": "При повороті праворуч на дорозі з двостороннім рухом водій має розташувати автомобіль трохи лівіше від середини дороги, залишаючись на своїй половині, готуючись до повороту.", "explSpecific": "Правильно — «Слева от середины дороги». Розташування по обидва боки середини суперечить правилу займати лише свою половину дороги; крайні позиції не є коректними для підготовки саме до правого повороту."}, {"num": 446, "text": "Что должен сделать водитель, прежде чем повернуть направо с главной дороги на второстепенную?", "topic": "Перехрестя та кільцеві розв'язки", "options": ["Начать поворот перед встречным транспортом, так как он должен уступить дорогу транспорту, поворачивающему направо.", "Остановиться и подать сигнал другому транспорту, чтобы выехать направо с второстепенной дороги.", "Уступить дорогу встречному транспорту и пешеходам, переходящим дорогу на перекрестке.", "Остановиться и подать сигнал другому транспорту, чтобы выехать налево с второстепенной дороги."], "correct": 2, "expl": "Перш ніж повернути праворуч з головної дороги на другорядну, водій повинен поступитися дорогою зустрічному транспорту і пішоходам, які переходять дорогу на перехресті.", "explSpecific": "Правильно — «Уступить дорогу встречному транспорту и пешеходам, переходящим дорогу на перекрестке». Початок повороту перед зустрічним транспортом чи сигналізація іншим про виїзд ліворуч чи праворуч з другорядної дороги — небезпечні або недоречні дії."}, {"num": 447, "text": "Что из следующего должен сделать водитель перед въездом в туннель?", "topic": "Автомагістраль і тунелі", "options": ["Убедиться, что фары ближнего света включены.", "Включить аварийные огни, чтобы предупредить другой транспорт о своем присутствии.", "Использовать только фары ближнего света, если другой транспорт находится в туннеле.", "Убедиться, что фары дальнего света включены."], "correct": 0, "expl": "Перед в'їздом у тунель водій повинен переконатися, що увімкнені фари ближнього світла, — це стандартна вимога навіть удень, коли всередині тунелю темніше.", "explSpecific": "Правильно — «Убедиться, что фары ближнего света включены». Аварійні вогні без причини поломки чи умовне обмеження лише коли інший транспорт у тунелі — недоречні дії; дальнє світло в тунелі засліплює зустрічний транспорт."}, {"num": 448, "text": "Что должен делать водитель в случае аварии или поломки в туннеле?", "topic": "Автомагістраль і тунелі", "options": ["Подать сигнал другому транспорту о возможности обгона.", "Подайте автомобилю сзади сигнал о необходимости остановиться, и попросить водителя вызвать помощь на другом конце туннеля.", "При необходимости, развернуть автомобиль, чтобы освободить пространство для обгона другим транспортом.", "Заглушить двигатель и включить аварийные огни."], "correct": 3, "expl": "У разі аварії чи поломки в тунелі водій повинен заглушити двигун і увімкнути аварійні вогні, щоб мінімізувати ризик пожежі й попередити інших.", "explSpecific": "Правильно — «Заглушить двигатель и включить аварийные огни». Сигналізація іншим про можливість обгону чи розворот у тунелі — небезпечні дії; прохання водія ззаду викликати допомогу не замінює власних негайних дій."}, {"num": 449, "text": "Что делать водителю в случае пробки в туннеле?", "topic": "Автомагістраль і тунелі", "options": ["Остановиться у ближайшего аварийного выхода.", "Включите предупреждающие огни опасности.", "Покинуть транспортное средство.", "Держаться ближе к транспортному средству, едущему впереди."], "correct": 1, "expl": "У разі затору в тунелі водій повинен увімкнути аварійні (попереджувальні) вогні, щоб позначити свою присутність для транспорту позаду.", "explSpecific": "Правильно — «Включите предупреждающие огни опасности». Зупинка саме біля аварійного виходу без причини, залишення автомобіля без потреби чи наближення впритул до транспорту попереду — недоречні дії."}, {"num": 450, "text": "Что делать водителю в случае остановки движения в туннеле?", "topic": "Автомагістраль і тунелі", "options": ["Выбрать пониженную передачу и не глушите двигатель.", "Выехать из туннеля задним ходом.", "Включить передние и задние противотуманные фонари.", "Заглушить двигатель."], "correct": 3, "expl": "У разі зупинки руху в тунелі водій повинен заглушити двигун, щоб уникнути накопичення вихлопних газів у замкненому просторі.", "explSpecific": "Правильно — «Заглушить двигатель». Понижена передача без глушіння двигуна, виїзд заднім ходом з тунелю чи увімкнення протитуманних вогнів замість глушіння — недостатні чи небезпечні дії."}, {"num": 451, "text": "Что должен делать водитель, если его транспортное средство выходит из строя или он попадает в аварию в туннеле?", "topic": "Автомагістраль і тунелі", "options": ["Включить аварийные огни и идти в направлении аварийной станции, чтобы вызвать помощь.", "Подать сигнал другому транспорту о необходимости остановиться.", "Выключить все огни и дожидаться помощи внутри автомобиля.", "Подать сигнал другому транспорту о возможности обгона."], "correct": 0, "expl": "Якщо транспортний засіб вийшов з ладу чи потрапив в аварію в тунелі, водій повинен увімкнути аварійні вогні і йти до найближчої аварійної станції для виклику допомоги.", "explSpecific": "Правильно — «Включить аварийные огни и идти в направлении аварийной станции, чтобы вызвать помощь». Сигналізація іншим про потребу зупинитися не є діями самого постраждалого водія; очікування допомоги всередині авто з вимкненими вогнями небезпечне."}, {"num": 452, "text": "Что делать водителю в случае возгорания автомобиля в туннеле?", "topic": "Автомагістраль і тунелі", "options": ["Подъехать к ближайшей аварийной станции.", "Подъехать к ближайшему аварийному выходу.", "Покинуть транспортное средство и использовать огнетушители, предусмотренные в туннеле, для тушения пожара.", "Покинуть транспортное средство и двигаться по направлению к аварийному выходу."], "correct": 3, "expl": "У разі загоряння автомобіля в тунелі водій повинен негайно залишити транспортний засіб і рухатися до найближчого аварійного виходу, а не намагатися самостійно гасити серйозну пожежу.", "explSpecific": "Правильно — «Покинуть транспортное средство и двигаться по направлению к аварийному выходу». Під'їзд до аварійної станції чи виходу з увімкненим пожежею автомобілем небезпечний; самостійне гасіння пожежі ризиковане для непідготовленої людини."}, {"num": 453, "text": "Что должен делать водитель на подъезде к перекрестку, на котором пешеход переходит дорогу?", "topic": "Пішоходи, велосипедисти, мотоциклісти", "options": ["Посигналить пешеходу.", "Пропустить пешехода.", "Успеть проехать перед пешеходом.", "Найти светофор."], "correct": 1, "expl": "Наближаючись до перехрестя, де пішохід переходить дорогу, водій зобов'язаний пропустити його, а не намагатися просигналити чи проїхати першим.", "explSpecific": "Правильно — «Пропустить пешехода». Сигнал клаксоном, спроба проїхати першим чи пошук світлофора (якого може й не бути) не відповідають обов'язку поступитися пішоходу на переході."}, {"num": 454, "text": "Что делать водителю, если ему мешает велосипедист, едущий перед ним.", "topic": "Пішоходи, велосипедисти, мотоциклісти", "options": ["Набрать скорость и обогнать велосипедиста.", "Посигналить велосипедисту, чтобы он съехал с дороги.", "Держаться поближе, пока не появится возможность безопасного обгона.", "Держаться подальше, пока не появится возможность безопасного обгона."], "correct": 3, "expl": "Якщо велосипедист попереду заважає рухатися з бажаною швидкістю, водій повинен триматися на безпечній дистанції, доки не з'явиться можливість безпечного обгону, а не тиснути на нього.", "explSpecific": "Правильно — «Держаться подальше, пока не появится возможность безопасного обгона». Прискорення для негайного обгону чи сигнал велосипедисту «з'їхати з дороги» — небезпечні або неввічливі дії."}, {"num": 455, "text": "Что делать водителю, если когда на светофоре, на котором он находится, загорается зеленый свет, пешеходы все еще переходят дорогу?", "topic": "Пішоходи, велосипедисти, мотоциклісти", "options": ["Подождать сколько нужно, чтобы они могли полностью перейти дорогу.", "Посигналить, чтобы предупредить пешеходов, что свет светофора изменился.", "Двигаться вперед, чтобы они побыстрее завершили переход.", "Подайте пешеходам сигнал о том, что свет светофора изменился, и продолжить движение."], "correct": 0, "expl": "Якщо на світлофорі водія загорівся зелений, а пішоходи ще не завершили перехід, водій повинен зачекати, скільки потрібно, доки вони повністю не перейдуть дорогу.", "explSpecific": "Правильно — «Подождать сколько нужно, чтобы они могли полностью перейти дорогу». Сигнал клаксоном чи рух вперед, щоб «підігнати» пішоходів, — неправомірний тиск на пішоходів, які мають пріоритет завершити перехід."}, {"num": 456, "text": "Что должен делать водитель, когда он видит впереди медленно движущееся транспортное средство, управляемое водителем-учеником?", "topic": "Обгін та зміна смуги руху", "options": ["Обгонять его как можно быстрее.", "Соблюдать дистанцию, чтобы избежать чрезмерного давления.", "Подъехать ближе к автомобилю, чтобы водитель ехал быстро.", "Подъехать ближе к автомобилю, чтобы сообщить о намерении совершить обгон."], "correct": 1, "expl": "Позаду повільного учнівського водія варто зберігати нормальну дистанцію, не тиснучи на нього психологічно наближенням впритул, і чекати безпечної можливості для обгону.", "explSpecific": "Правильно — «Соблюдать дистанцию, чтобы избежать чрезмерного давления». Спроба обігнати якнайшвидше без оцінки безпеки чи наближення впритул — небезпечні й неввічливі дії."}, {"num": 457, "text": "Как водитель-ученик может реагировать в необычных дорожных ситуациях?", "topic": "Штрафні бали, права та документи", "options": ["Медленнее, чем опытный водитель.", "Быстрее, чем опытный водитель.", "Также как и опытный водитель.", "Лучше, чем опытный водитель."], "correct": 0, "expl": "Водій-учень має менше досвіду розпізнавання і реагування на нестандартні дорожні ситуації, тому реагує повільніше, ніж досвідчений водій.", "explSpecific": "Правильно — «Медленнее, чем опытный водитель». Твердження про однакову, швидшу чи кращу реакцію не відповідають реальному рівню досвіду учня."}, {"num": 458, "text": "Что делать водителю, если он видит впереди велосипедиста, который собирается обогнать припаркованный автомобиль при отсутствии встречного транспорта.", "topic": "Пішоходи, велосипедисти, мотоциклісти", "options": ["Позволить велосипедисту обогнать припаркованный автомобиль, а затем продолжить движение.", "Не позволять ему обгонять припаркованный автомобиль.", "Подать сигнал, чтобы велосипедист не нарушал правила.", "Набрать скорость и обогнать велосипедиста."], "correct": 0, "expl": "Якщо велосипедист попереду збирається обігнати припаркований автомобіль, а зустрічного транспорту немає, водій повинен дати йому спокійно завершити маневр, перш ніж продовжити рух.", "explSpecific": "Правильно — «Позволить велосипедисту обогнать припаркованный автомобиль, а затем продолжить движение». Заборона обгону велосипедисту чи спроба обігнати його самому — недоречні або небезпечні втручання."}, {"num": 459, "text": "Что нужно знать водителю при повороте налево на боковую дорогу?", "topic": "Обгін та зміна смуги руху", "options": ["У следующего за вами транспорта должно быть достаточно пространства для обгона.", "Велосипедисты могут появиться слева (рядом).", "Подъехать как можно ближе к бордюру.", "Велосипедисты могут появиться справа."], "correct": 1, "expl": "Повертаючи ліворуч на бічну дорогу, водій повинен пам'ятати, що велосипедист може одночасно рухатися прямо вздовж його лівого боку, залишаючись непоміченим у сліпій зоні.", "explSpecific": "Правильно — «Велосипедисты могут появиться слева (рядом)». Достатність простору для обгону транспорту позаду не є головною небезпекою саме при повороті ліворуч; поява велосипедиста справа менш імовірна тут."}, {"num": 460, "text": "На перекрестках какой тип участников дорожного движения особенно уязвим?", "topic": "Перехрестя та кільцеві розв'язки", "options": ["Водители транспортных средств.", "Пешеходы.", "Водители тракторов.", "Водители грузовиков."], "correct": 1, "expl": "На перехрестях особливо вразливі пішоходи, оскільки вони найменш захищені й найменш помітні серед усіх учасників дорожнього руху.", "explSpecific": "Правильно — «Пешеходы». Водії транспортних засобів, тракторів чи вантажівок перебувають у захищеному кузові автомобіля і менш вразливі, ніж пішоходи."}, {"num": 461, "text": "На каких участников дорожного движения, появляющихся с левой стороны, водитель должен обращать особое внимание стоя на светофоре?", "topic": "Дорожні знаки та розмітка", "options": ["Фургоны.", "Мотоциклисты.", "Автомобили.", "Тракторы."], "correct": 1, "expl": "Стоячи на світлофорі, водій повинен особливо уважно стежити за учасниками руху, яких важко помітити через їх меншу видимість, — і мотоциклісти якраз належать до цієї вразливої категорії.", "explSpecific": "Правильно — «Мотоциклисты». Фургони й автомобілі мають значно більший силует і легше помітні; трактори рухаються повільно й також більш помітні через розмір — тоді як вузький силует мотоцикла найлегше загубити периферійним зором зліва."}, {"num": 462, "text": "Что должен делать водитель, когда собирается повернуть налево на оживленном перекрестке, и вокруг него находятся пешеходы и велосипедисты?", "topic": "Пішоходи, велосипедисти, мотоциклісти", "options": ["Держаться ближе к левому краю, чтобы велосипедисты или пешеходы не могли подъехать с левой стороны.", "Следить за велосипедистами или пешеходами, которые могут попытаться перейти дорогу перед автомобилем.", "Включить левый поворот, посмотреть в правое зеркало и сделать поворот, когда дорога освободится.", "Держаться правее, чтобы освободить место для велосипедистов."], "correct": 1, "expl": "Повертаючи ліворуч на жвавому перехресті серед пішоходів і велосипедистів, водій повинен уважно стежити за тими, хто може спробувати перейти дорогу прямо перед автомобілем.", "explSpecific": "Правильно — «Следить за велосипедистами или пешеходами, которые могут попытаться перейти дорогу перед автомобилем». Утримання лівого краю, щоб «блокувати» велосипедистів, — недоречний маневр замість пильного спостереження."}, {"num": 463, "text": "На присутствие каких участников дорожного движения водитель должен периодически проверять свои слепые зоны в медленном городском потоке?", "topic": "Пішоходи, велосипедисти, мотоциклісти", "options": ["Велосипедистов.", "Такси.", "Фургонов.", "Автомобилей."], "correct": 0, "expl": "У повільному міському потоці водій повинен періодично перевіряти сліпі зони саме на присутність велосипедистів, чий вузький силует найлегше не помітити.", "explSpecific": "Правильно — «Велосипедистов». Таксі, фургони й автомобілі мають значно більший силует і легше помітні у порівнянні з вузьким профілем велосипеда."}, {"num": 464, "text": "Если владелец транспортного средства позволяет водителю-ученику управлять своим транспортным средством, какой максимальный штраф предусмотрен для владельца в этом случае?", "topic": "Штрафні бали, права та документи", "options": ["1 000 евро.", "2 000 евро.", "1 500 евро.", "500 евро."], "correct": 0, "expl": "Власник транспортного засобу, який дозволяє водієві-учню керувати автомобілем без належного супроводу, може отримати штраф до 1 000 євро.", "explSpecific": "Правильно — «1 000 евро». Суми 500, 1 500 чи 2 000 євро — вигадані, не відповідають встановленому максимальному штрафу для власника."}, {"num": 465, "text": "Что должен делать водитель, если свет светофора меняется на зеленый, когда пешеходы все еще переходят дорогу на переходе с автоматическим светофором?", "topic": "Пішоходи, велосипедисти, мотоциклісти", "options": ["Увеличить обороты двигателя, чтобы пешеходы, услышав его, поспешили перейти дорогу.", "Посигналить и осторожно продолжить движение.", "Подать им сигнал, чтобы они шли быстрее.", "Терпеливо подождать, пока они не перейдут дорогу."], "correct": 3, "expl": "Якщо світло на переході з автоматичним світлофором змінюється на зелений, а пішоходи ще переходять, водій повинен терпляче зачекати, доки вони завершать перехід.", "explSpecific": "Правильно — «Терпеливо подождать, пока они не перейдут дорогу». Збільшення обертів двигуна чи подача сигналу «йти швидше» — неправомірний тиск на пішоходів, які мають пріоритет завершити перехід."}, {"num": 466, "text": "На каких участников дорожного движения, появляющихся с левой стороны, водитель должен обращать особое внимание стоя на светофоре?", "topic": "Дорожні знаки та розмітка", "options": ["Фургоны.", "Велосипедистов.", "Тракторы.", "Автомобили."], "correct": 1, "expl": "Той самий принцип підвищеної уваги стосується велосипедистів, чий вузький силует і низька швидкість роблять їх легко непоміченими периферійним зором.", "explSpecific": "Правильно — «Велосипедистов». Фургони, трактори й автомобілі значно більші за розміром і помітніші; саме вузький, часто тихий силует велосипедиста найлегше пропустити повз увагу, особливо зліва від водія."}, {"num": 467, "text": "Что должен делать водитель если на дороге впереди видит детей?", "topic": "Погодні умови та видимість", "options": ["Сохраняйте скорость, но будьте готовы остановиться, при необходимости.", "Посигналить и продолжить движение на обычной скорости.", "Включить фары, чтобы предупредить детей о своем присутствии.", "Снизить скорость и быть готовым остановиться, при необходимости."], "correct": 3, "expl": "Побачивши дітей на дорозі попереду, водій повинен знизити швидкість і бути готовим зупинитися будь-якої миті, оскільки поведінка дітей непередбачувана.", "explSpecific": "Правильно — «Снизить скорость и быть готовым остановиться, при необходимости». Збереження швидкості, сигнал з продовженням руху чи лише увімкнення фар — недостатні заходи."}, {"num": 468, "text": "Что должен делать водитель, когда собирается повернуть налево на перекрестке, и вокруг него находятся пешеходы и велосипедисты?", "topic": "Пішоходи, велосипедисти, мотоциклісти", "options": ["Посмотреть в правое зеркало, повернуть и посигналить.", "Включить левый поворот, посмотреть в правое зеркало и повернуть.", "Посмотреть в зеркала и следить за велосипедами или пешеходами слева.", "Подать звуковой сигнал, продолжая движение, предупреждая таким образом других участников дорожного движения о намерении повернуть."], "correct": 2, "expl": "Повертаючи ліворуч на перехресті серед пішоходів і велосипедистів, водій повинен подивитися в дзеркала і стежити саме за учасниками руху зліва — з боку, куди він повертає.", "explSpecific": "Правильно — «Посмотреть в зеркала и следить за велосипедами или пешеходами слева». Погляд лише у праве дзеркало чи звуковий сигнал замість спостереження — недостатні заходи безпеки саме для лівого повороту."}, {"num": 469, "text": "Кто из следующих участников дорожного движения наиболее уязвим в медленном городском потоке?", "topic": "Пішоходи, велосипедисти, мотоциклісти", "options": ["Автомобили.", "Пешеходы.", "Такси.", "Фургоны."], "correct": 1, "expl": "У повільному міському потоці пішоходи — найвразливіші учасники руху, оскільки не мають жодного захисту від зіткнення з транспортом.", "explSpecific": "Правильно — «Пешеходы». Автомобілі, таксі й фургони — це самі транспортні засоби з певним захистом для тих, хто всередині, тоді як пішохід повністю незахищений."}, {"num": 470, "text": "Водитель подъезжает к перекрестку с автоматическим светофором, на котором мигает желтый свет, при этом на дороге все еще находится велосипедист. Как водителю следует поступить?", "topic": "Пішоходи, велосипедисти, мотоциклісти", "options": ["Посигналить и осторожно продолжить движение.", "Подождать и дать пешеходам перейти дорогу в их темпе.", "Попросить пешехода пройти как можно быстрее.", "Увеличить обороты двигателя, чтобы пешеходы, услышав его, поспешили перейти дорогу."], "correct": 1, "expl": "На перехресті з мигаючим жовтим світлом, де ще перебуває велосипедист чи пішохід, водій повинен зачекати і дати їм завершити перехід у своєму темпі.", "explSpecific": "Правильно — «Подождать и дать пешеходам перейти дорогу в их темпе». Сигнал клаксоном, прохання поспішити чи збільшення обертів двигуна — неправомірний тиск на учасника руху, що ще не завершив перехід."}, {"num": 471, "text": "Что должен делать водитель во время движения ночью по неосвещенной дороге?", "topic": "Пішоходи, велосипедисти, мотоциклісти", "options": ["Ехать по центру дороги.", "Двигаться левее, чтобы избежать встречного движения.", "Остерегаться пешеходов в темной одежде.", "Подъехать как можно ближе к отражающей линии."], "correct": 2, "expl": "На неосвітленій дорозі вночі водій повинен особливо остерігатися пішоходів у темному одязі, яких вкрай важко вчасно помітити фарами.", "explSpecific": "Правильно — «Остерегаться пешеходов в темной одежде». Рух по центру дороги чи зміщення ліворуч «щоб уникнути зустрічного руху» — небезпечні маневри; наближення до відбивної лінії не є основною рекомендованою тактикою."}, {"num": 472, "text": "Что должен делать водитель, если видит слева бегунов?", "topic": "Обгін та зміна смуги руху", "options": ["Посмотреть в зеркала, включить поворот и совершить обгон, предоставив им достаточно пространства.", "Подождать, пока они не уйдут с пути водителя.", "Включить поворот и обогнать, предоставив им достаточно пространства.", "Подать звуковой сигнал и включить фары, чтобы предупредить их о своем присутствии."], "correct": 0, "expl": "Обганяючи бігунів на дорозі, водій має дотримуватися стандартної послідовності безпечного обгону: дзеркала, сигнал, а потім сам маневр з достатньою бічною дистанцією.", "explSpecific": "Правильно — «Посмотреть в зеркала, включить поворот и совершить обгон, предоставив им достаточно пространства». Очікування, поки бігуни самі зійдуть з дороги, — пасивна стратегія; звуковий сигнал і фари можуть налякати бігунів."}, {"num": 473, "text": "Что должен делать водитель, когда едет по дороге с выбоинами и впереди велосипедист?", "topic": "Пішоходи, велосипедисти, мотоциклісти", "options": ["Дождаться, пока велосипедист не отъедет влево, и сохраняйте скорость.", "Продолжить движение и подать звуковой сигнал, чтобы предупредить велосипедиста о своем приближении.", "Переключиться на пониженную передачу и быстро совершить обгон.", "Оставить дополнительное пространство на случай, если велосипедист уклониться в сторону, чтобы объехать выбоину."], "correct": 3, "expl": "Проїжджаючи повз велосипедиста дорогою з вибоїнами, водій повинен залишити додатковий простір, оскільки велосипедист може раптово вильнути вбік, об'їжджаючи яму.", "explSpecific": "Правильно — «Оставить дополнительное пространство на случай, если велосипедист уклонится в сторону, чтобы объехать выбоину». Очікування, що велосипедист сам відʼїде, чи швидкий обгін на пониженій передачі — недостатньо безпечні реакції."}, {"num": 474, "text": "Что такое неконтролируемый пешеходный переход?", "topic": "Пішоходи, велосипедисти, мотоциклісти", "options": ["Пешеходный переход со знаком \"Смотри вправо\" на проезжей части.", "Пешеходный переход с мигающим желтым светом.", "Место неконтролируемого пешеходного перехода.", "Пешеходный переход на пешеходной улице."], "correct": 2, "expl": "Неконтрольований пішохідний перехід — це перехід без світлофора чи регулювальника, де пріоритет пішоходів визначається самою розміткою переходу, а не додатковими сигналами.", "explSpecific": "Правильно — «Место неконтролируемого пешеходного перехода». Знак «дивись праворуч» чи мигаючий жовтий стосуються геть інших, регульованих типів переходу; прив'язка до пішохідної вулиці не є визначенням неконтрольованого переходу."}, {"num": 475, "text": "Как пешеход, идущий по плохо освещенной дороге, может снизить риск несчастного случая?", "topic": "Пішоходи, велосипедисти, мотоциклісти", "options": ["Носить темную одежду.", "Ходить вместе с группой.", "Идти по левой части дороги.", "Носить яркую одежду."], "correct": 3, "expl": "Пішохід на погано освітленій дорозі може значно знизити ризик, одягнувши яскравий (світловідбивний) одяг, який робить його помітним для водіїв здалеку.", "explSpecific": "Правильно — «Носить яркую одежду». Темний одяг, навпаки, підвищує ризик; рух групою чи по лівій частині дороги не мають прямого стосунку до видимості пішохода самого по собі."}, {"num": 476, "text": "Если обгон велосипедиста в зонах с разрешенной скоростью более 50 км/ч безопасен, каково минимальное рекомендуемое расстояние проезда?", "topic": "Обгін та зміна смуги руху", "options": ["Максимум 1,75 метра.", "Минимум 1 метр.", "Минимум 1,5 метра.", "Максимум 1,5 метра."], "correct": 2, "expl": "У зонах з дозволеною швидкістю понад 50 км/год мінімальна рекомендована бічна дистанція при обгоні велосипедиста становить 1,5 метра.", "explSpecific": "Правильно — «Минимум 1,5 метра». Формулювання «максимум» замість «мінімум» перевертає сенс правила; «мінімум 1 метр» — норма для зон з нижчою дозволеною швидкістю."}, {"num": 477, "text": "Во время движения по проселочной дороге без тротуаров, какие участники дорожного движения могут приближаться к нему по своей стороне дороги?", "topic": "Пішоходи, велосипедисти, мотоциклісти", "options": ["Велосипедисты.", "Тракторы.", "Пешеходы.", "Мотоциклисты."], "correct": 2, "expl": "На путівцевій (проселочній) дорозі без тротуарів пішоходи, за правилами, наближаються до водія по своїй (лівій) стороні дороги, назустріч транспорту.", "explSpecific": "Правильно — «Пешеходы». Велосипедисти, трактори й мотоциклісти рухаються як частина транспортного потоку по правій стороні, а не назустріч по лівій, як пішоходи без тротуару."}, {"num": 478, "text": "Что должен делать водитель во время движения ночью по неосвещенной дороге?", "topic": "Пішоходи, велосипедисти, мотоциклісти", "options": ["Ехать по центру дороги.", "Двигаться левее, чтобы избежать встречного движения.", "Остерегаться пешеходов в темной одежде.", "Подъехать как можно ближе к отражающей линии."], "correct": 2, "expl": "На неосвітленій дорозі вночі водій повинен особливо остерігатися пішоходів у темному одязі, яких вкрай важко вчасно помітити фарами.", "explSpecific": "Правильно — «Остерегаться пешеходов в темной одежде». Рух по центру дороги чи зміщення ліворуч — небезпечні маневри; наближення до відбивної лінії не є основною рекомендованою тактикою."}, {"num": 479, "text": "Если нет пешеходной дорожки, где должен ходить пешеход?", "topic": "Пішоходи, велосипедисти, мотоциклісти", "options": ["Левая сторона дороги.", "1 метр от края дороги.", "Правая сторона дороги.", "Никакого регулирования нет."], "correct": 2, "expl": "За відсутності тротуару пішохід повинен йти правою стороною дороги — тим самим правилом, що вже наводилося раніше в цій темі.", "explSpecific": "Правильно — «Правая сторона дороги». «Ліва сторона» суперечить встановленому правилу руху назустріч транспорту; «1 метр від краю» — вигадана деталь; «немає регулювання» ігнорує існування чіткої норми."}, {"num": 480, "text": "Каковы действия водителя, намеревающегося обогнать велосипедиста, едущего в том же направлении впереди?", "topic": "Обгін та зміна смуги руху", "options": ["Посмотреть в зеркало, включить поворот и начать обгон, если это безопасно.", "Посмотреть в зеркало и выехать, чтобы совершить обгон, не включая поворот.", "Включить поворот, начать обгон и посмотреть в зеркало.", "Включить поворот, посмотреть в зеркало, начать обгон, когда это будет безопасно."], "correct": 0, "expl": "Обганяючи велосипедиста, що рухається попереду в тому ж напрямку, водій дотримується тієї самої стандартної послідовності: дзеркало, сигнал, а потім сам маневр лише за умови безпеки.", "explSpecific": "Правильно — «Посмотреть в зеркало, включить поворот и начать обгон, если это безопасно». Обгін без сигналу чи в неправильному порядку дій порушують стандартну безпечну послідовність."}, {"num": 481, "text": "Если водитель подозревает, что его сигналы поворота не видны, что ему следует делать?", "topic": "Загальні правила та поведінка на дорозі", "options": ["Подать также четкий, решительный сигнал рукой.", "Нет необходимости подавать сигналы при условии наблюдения за обстановкой.", "Позиция водителя на дороге является достаточным сигналом.", "Выкрикнуть из окна, сообщая о своих намерениях."], "correct": 0, "expl": "Якщо водій підозрює, що електричні покажчики повороту не помітні, варто продублювати намір чітким сигналом рукою.", "explSpecific": "Правильно — «Подать также четкий, решительный сигнал рукой». Відмова від додаткового сигналу, покладання лише на позицію на дорозі чи крик з вікна — ненадійні способи повідомити про намір."}, {"num": 482, "text": "Что должен делать водитель, когда едет по проселочной дороге, при этом за ним едут другие транспортные средства, а по дороге идут пешеходы?", "topic": "Пішоходи, велосипедисти, мотоциклісти", "options": ["Подать сигнал о своем намерении обогнать пешеходов.", "Подать пешеходам знак о том, чтобы они ушли с дороги.", "Оставить минимальный зазор 30 сантиметров.", "Моргнуть фарами, чтобы предупредить о пешеходах на дороге следующий за ним транспорт."], "correct": 0, "expl": "Проїжджаючи повз пішоходів на путівцевій дорозі, коли позаду рухається інший транспорт, водій повинен чітко просигналізувати про намір обігнати пішоходів, щоб транспорт позаду розумів його дії.", "explSpecific": "Правильно — «Подать сигнал о своем намерении обогнать пешеходов». Подача знаку самим пішоходам «зійти з дороги» неввічлива; фіксована відстань 30 см надто мала для безпечного обгону."}, {"num": 483, "text": "0 чем должен знать водитель при движении зимой в темное время по утрам и вечерам по неосвещенным проселочным дорогам?", "topic": "Пішоходи, велосипедисти, мотоциклісти", "options": ["Водитель должен постоянно ездить с включенными габаритными фонарями, чтобы иметь возможность видеть пешеходов, идущих по неосвещенным проселочным дорогам.", "Школьники более уязвимы на неосвещенных проселочных дорогах темными зимними утрами и вечерами.", "Водитель должен ожидать, что пешеходы окажутся на тротуаре и не будут подвергнуты опасности столкновения.", "О том, что отсутствие света не повлияет на способность водителя видеть бездомных животных на дороге."], "correct": 1, "expl": "Взимку темними ранками й вечорами школярі особливо вразливі на неосвітлених путівцевих дорогах, оскільки саме в цей час вони йдуть до школи чи додому в умовах поганої видимості.", "explSpecific": "Правильно — «Школьники более уязвимы на неосвещенных проселочных дорогах темными зимними утрами и вечерами». Постійне увімкнення лише габаритів недостатньо для повноцінного освітлення; впевненість, що пішоходи будуть на тротуарі, — недбале припущення."}, {"num": 484, "text": "Если обгон велосипедиста в зонах с разрешенной скоростью более 50 км/ч безопасен, каково минимальное рекомендуемое расстояние проезда?", "topic": "Обгін та зміна смуги руху", "options": ["Минимум 1 метр.", "Минимум 2 метра.", "Максимум 3 метра.", "Минимум 3 метра."], "correct": 0, "expl": "У зонах з дозволеною швидкістю понад 50 км/год загальна рекомендація — витримувати щонайменше 1 метр бічної дистанції при обгоні велосипедиста.", "explSpecific": "Правильно — «Минимум 1 метр». «Максимум 3 метра» і «мінімум 2/3 метра» не відповідають встановленому значенню; формулювання «мінімум» підкреслює нижню межу безпеки."}, {"num": 485, "text": "Какой минимальный штраф грозит водителю-ученику, которого остановила Гарда за вождение без сопровождения?", "topic": "Штрафні бали, права та документи", "options": ["120 евро", "80 евро", "100 евро", "140 евро"], "correct": 1, "expl": "Мінімальний штраф для водія-учня, якого Гарда зупинила за керування без супроводу, становить 80 євро.", "explSpecific": "Правильно — «80 евро». Суми 100, 120 чи 140 євро — вищі за мінімальний, встановлений законом штраф у цій ситуації."}, {"num": 486, "text": "Какое ограничение применяется к постоянному водительскому удостоверению, если его владелец сдал экзамен по вождению на автомобиле с автоматической коробкой передач?", "topic": "Штрафні бали, права та документи", "options": ["Они не могут управлять транспортными средствами с механической коробкой передач.", "Они не могут ездить по автомагистралям.", "Они должны продолжать показывать предупреждающие знаки.", "Они не могут двигаться со скоростью более 80 км/ч."], "correct": 0, "expl": "Постійне посвідчення, отримане на іспиті з автоматичною коробкою передач, обмежує власника лише автомобілями з автоматичною коробкою.", "explSpecific": "Правильно — «Они не могут управлять транспортными средствами с механической коробкой передач». Заборона їзди автомагістраллю, обов'язкові попереджувальні знаки чи обмеження швидкості 80 км/год — вигадані умови."}, {"num": 487, "text": "По каким дорогам разрешено ездить учащимся?", "topic": "Автомагістраль і тунелі", "options": ["Все дороги, кроме автомагистралей и двухполосных дорог.", "Все дороги, кроме двухполосных дорог.", "Все дороги, кроме автострад.", "Все дороги, кроме автомагистралей."], "correct": 3, "expl": "Водії-учні можуть їздити всіма дорогами, крім автомагістралей, на які їм в'їзд заборонений.", "explSpecific": "Правильно — «Все дороги, кроме автомагистралей». Виключення двосмугових доріг чи автострад — неточні, оскільки саме автомагістралі є єдиною забороненою для учнів категорією доріг."}, {"num": 488, "text": "По каким дорогам запрещено ездить учащимся?", "topic": "Автомагістраль і тунелі", "options": ["Они не могут ездить по автомагистралям.", "Они не могут ездить по двухполосным дорогам.", "Они не могут ездить по проселочным дорогам.", "Они не могут ездить по автострадам."], "correct": 0, "expl": "Той самий факт, сформульований як заборона: учням заборонено їздити саме автомагістралями.", "explSpecific": "Правильно — «Они не могут ездить по автомагистралям». Двосмугові, путівцеві дороги чи автостради не входять до забороненого для учнів переліку — заборона стосується виключно автомагістралей."}, {"num": 489, "text": "Какими должны быть предупреждающие знаки на учебном автомобиле?", "topic": "Загальні правила та поведінка на дорозі", "options": ["Красная буква L на белом фоне.", "Белая буква L на красном фоне.", "Красная буква L на прозрачном фоне.", "Зеленая буква L на белом фоне."], "correct": 0, "expl": "В Ірландії учнівський автомобіль позначається стандартною табличкою — червона літера L на білому фоні.", "explSpecific": "Правильно — «Красная буква L на белом фоне». Інші комбінації кольорів не відповідають офіційному стандарту знаку учня-водія."}, {"num": 490, "text": "Какой штраф предусмотрен для водителя-ученика за вождение автомобиля без сопровождения?", "topic": "Штрафні бали, права та документи", "options": ["120 евро.", "140 евро.", "80 евро.", "100 евро."], "correct": 0, "expl": "За керування автомобілем без супроводу водій-учень отримує штраф у розмірі 120 євро.", "explSpecific": "Правильно — «120 евро». Суми 80, 100 чи 140 євро не відповідають встановленому штрафу саме за це порушення."}, {"num": 491, "text": "Где водители могут найти информацию о максимально разрешенной массе своего автомобиля?", "topic": "Штрафні бали, права та документи", "options": ["На табличке NCT.", "На металлической пластине на автомобиле.", "На наклейке об уплате страховки.", "На наклейке об уплате дорожного налога."], "correct": 1, "expl": "Максимально дозволену масу автомобіля водії можуть знайти на металевій табличці, встановленій виробником на самому автомобілі.", "explSpecific": "Правильно — «На металлической пластине на автомобиле». Табличка NCT, наклейка про страховку чи про дорожній податок не містять інформації про максимально дозволену масу транспортного засобу."}, {"num": 492, "text": "Разрешено ли использовать транспортное средство в общественных местах без наклейки об уплате дорожного налога.", "topic": "Загальні правила та поведінка на дорозі", "options": ["Да, если только после истечения срока действия предыдущей наклейки прошло не более 10 дней.", "Нет, только на старинные автомобили не наклеивается наклейка об уплате дорожного налога.", "Да, если только после истечения срока действия предыдущей наклейки прошло не более одного месяца.", "Нет, на всех транспортных средствах должна быть наклейка об уплате дорожного налога."], "correct": 3, "expl": "Кожен транспортний засіб на дорогах загального користування повинен мати чинну наклейку про сплату дорожнього податку — без винятків за типом авто чи короткого пільгового періоду.", "explSpecific": "Правильно — «Нет, на всех транспортных средствах должна быть наклейка». Винятки для старовинних автомобілів чи пільгові періоди в 10 днів або місяць — вигадані, не передбачені правилом послаблення."}, {"num": 493, "text": "Что делать водителю, если он хочет сесть за руль транспортного средства, но срок действия наклейки об уплате дорожного налога истек?", "topic": "Загальні правила та поведінка на дорозі", "options": ["Разрешается управлять автомобилем только в экстренных случаях.", "Он немедленно должен оплатить дорожный налог.", "Он должен оплатить дорожный налог в течение 10 дней с момента истечения.", "Он должен связаться с Гардой, чтобы получить подтверждение."], "correct": 1, "expl": "Якщо термін дії наклейки про сплату дорожнього податку минув, водій зобов'язаний невідкладно сплатити податок, а не чекати чи їздити далі без нього.", "explSpecific": "Правильно — «Он немедленно должен оплатить дорожный налог». Дозвіл їздити лише в екстрених випадках, пільговий 10-денний період чи звернення до поліції за підтвердженням — вигадані винятки."}, {"num": 494, "text": "Сколько штрафных баллов предусматривается за управление транспортным средством водителем-учеником без сопровождения?", "topic": "Штрафні бали, права та документи", "options": ["2 штрафных балла.", "3 штрафных балла.", "4 штрафных балла.", "5 штрафных балла."], "correct": 2, "expl": "За керування автомобілем без супроводу водій-учень отримує 4 штрафних бали.", "explSpecific": "Правильно — «4 штрафных балла». 2, 3 чи 5 балів не відповідають встановленій кількості штрафних балів за це порушення."}, {"num": 495, "text": "Когда транспортным средством управляет лицо, которое не является его владельцем, кто отвечает за уплату дорожного налога и отображения действующей наклейки об уплате дорожного налога?", "topic": "Загальні правила та поведінка на дорозі", "options": ["Гарда несет полную ответственность за это.", "Водитель и или владелец транспортного средства несут за это ответственность.", "Только водитель несет за это ответственность.", "Только владелец несет за это ответственность."], "correct": 1, "expl": "Відповідальність за сплату дорожнього податку й наявність чинної наклейки лежить і на водієві, і на власникові транспортного засобу спільно, а не лише на одному з них.", "explSpecific": "Правильно — «Водитель и или владелец транспортного средства несут за это ответственность». Покладання відповідальності виключно на Гарду, лише на водія чи лише на власника не відображає спільний характер обов'язку."}, {"num": 496, "text": "Когда действующая наклейка об уплате дорожного налога должна быть нанесена на новый автомобиль для движения по дороге общественного пользования.", "topic": "Автомагістраль і тунелі", "options": ["Не позднее 10 дней после регистрации.", "Только при движении по автомагистрали.", "Всегда, когда автомобиль находится на дороге общего пользования.", "В течение 1 месяца после регистрации."], "correct": 2, "expl": "Чинна наклейка про сплату дорожнього податку повинна бути на новому автомобілі завжди, коли він перебуває на дорозі загального користування, без відстрочки.", "explSpecific": "Правильно — «Всегда, когда автомобиль находится на дороге общего пользования». Відстрочка на 10 днів чи місяць після реєстрації, або прив'язка лише до руху автомагістраллю, — вигадані винятки."}, {"num": 497, "text": "Кто имеет право требовать предъявить документ о регистрации транспортного средства водителя?", "topic": "Штрафні бали, права та документи", "options": ["Любой персонал пожарной охраны или скорой помощи на месте столкновения, в котором участвовало ваше транспортное средство.", "Гарда может попросить вас предъявить документы о регистрации транспортного средства на соответствующей станции Гарды.", "Член компании по эвакуации автомобилей или любой, кто оказывает помощь в эвакуации.", "Любой человек, с которым водитель участвует в столкновении."], "correct": 1, "expl": "Право вимагати пред'явлення документа про реєстрацію транспортного засобу на станції Гарди має саме Гарда (поліція).", "explSpecific": "Правильно — «Гарда может попросить вас предъявить документы о регистрации транспортного средства на соответствующей станции Гарды». Персонал пожежної чи швидкої допомоги, працівники евакуаторів чи будь-яка особа, що потрапила в зіткнення, не мають такого повноваження."}, {"num": 498, "text": "Если транспортным средством управляет кто-то, кто не является владельцем, но имеет согласие его владельца, кто должен обеспечить надлежащую страховку водителя?", "topic": "Штрафні бали, права та документи", "options": ["Страховая компания.", "Только владелец транспортного средства.", "Водитель и владелец транспортного средства.", "Только водитель."], "correct": 2, "expl": "Якщо автомобілем керує особа за згодою власника, відповідальність за належне страхування водія несуть обидва — і водій, і власник транспортного засобу.", "explSpecific": "Правильно — «Водитель и владелец транспортного средства». Відповідальність лише страхової компанії, лише власника чи лише водія не відображає реальний розподіл обов'язків."}, {"num": 499, "text": "Застрахован ли водитель транспортного средства после истечения срока действия страхового полиса?", "topic": "Штрафні бали, права та документи", "options": ["Страховка водителя действует в течение 14 дней после истечения срока действия страхового полиса.", "Страховка водителя действует в течение 10 дней после истечения срока действия страхового полиса.", "Страховка водителя действует в течение 7 дней после истечения срока действия страхового полиса.", "После истечения срока действия полиса, водитель не является застрахованным."], "correct": 3, "expl": "Після закінчення строку дії страхового полісу водій одразу перестає бути застрахованим — жодного пільгового періоду немає.", "explSpecific": "Правильно — «После истечения срока действия полиса, водитель не является застрахованным». Твердження про пільгові періоди 7, 10 чи 14 днів після закінчення строку — вигадані."}, {"num": 500, "text": "Если водитель желает управлять другим транспортным средством, находящемся в частной собственности, но он не уверен, застрахован ли он для управления этим транспортным средством, что ему следует делать?", "topic": "Штрафні бали, права та документи", "options": ["Управление разрешено при наличии на автомобиле действующей наклейки об уплате страховки.", "Переклеить наклейку об уплате страховки со своего автомобиля на автомобиль, за руль которого он желает сесть.", "Вождение разрешено при условии если он сообщит об этом в свою страховую компанию в течение 10 дней и согласится выплатить любую дополнительную премию.", "Водитель должен связаться со своим страховщиком, чтобы узнать, распространяется ли его страховое покрытие на вождение других автомобилей."], "correct": 3, "expl": "Якщо водій не впевнений, чи застрахований він для керування чужим приватним автомобілем, він повинен звернутися до свого страховика й уточнити це напряму.", "explSpecific": "Правильно — «Водитель должен связаться со своим страховщиком, чтобы узнать, распространяется ли его страховое покрытие на вождение других автомобилей». Керування лише за наявності наклейки про страховку на іншому авто, переклеювання власної наклейки чи їзда з подальшим повідомленням протягом 10 днів — незаконні припущення."}, {"num": 501, "text": "Когда водитель желает сесть за руль транспортного средства, и не уверен, застрахован ли он, что ему следует делать?", "topic": "Штрафні бали, права та документи", "options": ["Он должен обратиться за информацией в местную Станцию Гарды.", "Он должен обратиться за информацией в местное отделение Национальной службы выдачи водительских удостоверений (NDLS).", "Он должен обратиться за информацией в местное отделение Управления по налогообложению автомобилей.", "Он не должен управлять автомобилем, пока его страховая компания не подтвердит, что он застрахован."], "correct": 3, "expl": "Якщо водій не впевнений у своєму страхуванні, він не повинен сідати за кермо, доки страхова компанія не підтвердить наявність покриття.", "explSpecific": "Правильно — «Он не должен управлять автомобилем, пока его страховая компания не подтвердит, что он застрахован». Звернення до станції Гарди, NDLS чи податкового управління не підтверджує факт страхування — це вирішує лише страхова компанія."}, {"num": 502, "text": "Какое минимальное страховое покрытие необходимо водителю для движения по дороге общего пользования?", "topic": "Штрафні бали, права та документи", "options": ["Всесторонняя страховка.", "Индивидуальное страхование от несчастных случаев.", "Страхование при пожарах.", "Страхование ответственности перед третьими лицами."], "correct": 3, "expl": "Мінімальне обов'язкове страхове покриття для руху дорогою загального користування — страхування відповідальності перед третіми особами.", "explSpecific": "Правильно — «Страхование ответственности перед третьими лицами». Всебічна страховка перевищує мінімальні вимоги; страхування від нещасних випадків чи від пожеж не є обов'язковим мінімумом."}, {"num": 503, "text": "Как долго сопровождающий водитель водителя-ученика должен являться владельцем полноценного водительского удостоверения категории В?", "topic": "Штрафні бали, права та документи", "options": ["6 месяцев.", "3 года.", "1 год.", "2 года."], "correct": 3, "expl": "Супроводжуючий водія-учня повинен мати повне водійське посвідчення категорії B не менше 2 років.", "explSpecific": "Правильно — «2 года». 6 місяців, 1 рік чи 3 роки не відповідають встановленому законом мінімальному стажу супроводжуючого водія."}, {"num": 504, "text": "Если водитель хочет сесть за руль другого транспортного средства, по которому на данный момент не уплачен дорожный налог, сможет ли он перенести наклейку об уплате дорожного налога со своего автомобиля на автомобиль, за руль которого собирается сесть.", "topic": "Дитячі крісла та ремені безпеки", "options": ["Да, при условии, что его собственный автомобиль не будет использоваться одновременно.", "Только временно, если другое транспортное средство облагается более низкой ставкой налога.", "При обстоятельствах, когда соответствующая форма была заполнена и отправлена в местную налоговую инспекцию.", "Ни при каких обстоятельствах наклейку об уплате дорожного налога нельзя переносить на другое транспортное средство."], "correct": 3, "expl": "Ремінь безпеки і дитяче крісло працюють за одним принципом — розподілити силу удару по найміцніших частинах тіла і не дати людині вилетіти з салону чи вдаритись об внутрішні поверхні авто. Відповідальність за пристібання дітей молодшого віку лежить на водієві, а не на самій дитині чи батьках, які не за кермом — це і пояснює логіку відповідей у таких питаннях.", "explSpecific": "Правильна відповідь тут — «Ни при каких обстоятельствах наклейку об уплате дорожного налога нельзя переносить на другое транспортное средство». Інші варіанти в цьому питанні («Да, при условии, что его собственный автомобиль не будет использоваться одновременно», «Только временно, если другое транспортное средство облагается более низкой ставкой налога» та «При обстоятельствах, когда соответствующая форма была заполнена и отправлена в местную налоговую инспекцию») не відповідають цій вимозі й тому неправильні."}, {"num": 505, "text": "Что должен делать водитель, если он становится участником аварии, в которой никто не пострадал, но транспортные средства создают опасность или препятствие на дороге?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Высадить всех пассажиров и разместить красный предупреждающий треугольник на дороге.", "Соблюдать осторожность при перемещении поврежденных транспортных средств и приложить все усилия, чтобы предупредить другой транспорт.", "Остановить весь транспорт, пока не будет установлено, кто виноват.", "До приезда Гарды не перемещать транспортные средства."], "correct": 1, "expl": "Якщо в ДТП ніхто не постраждав, але транспорт створює перешкоду на дорозі, головне завдання водія — обережно прибрати перешкоду й попередити інших учасників руху про небезпеку.", "explSpecific": "Правильно — «Соблюдать осторожность при перемещении поврежденных транспортных средств и приложить все усилия, чтобы предупредить другой транспорт». Висадка пасажирів з розміщенням трикутника — лише часткова міра; повна зупинка руху чи заборона рухати авто до приїзду поліції невиправдано затримують усунення небезпеки."}, {"num": 506, "text": "Если водитель сдает экзамен на автомобиле с автоматической коробкой передач, на каких автомобилях он имеет право ездить?", "topic": "Автомагістраль і тунелі", "options": ["Только автомобилями с механической коробкой передач, входящими в категорию водительского удостоверения.", "Все транспортные средства в категории водительского удостоверения, но только автомобили с автоматической коробкой передач на автомагистрали.", "Только автомобилями с автоматической коробкой передач, входящими в категорию его водительского удостоверения.", "Все автомобили, входящие в категорию водительского удостоверения."], "correct": 2, "expl": "Якщо водій склав іспит на автомобілі з автоматичною коробкою передач, його посвідчення дійсне лише для автомобілів з автоматичною коробкою в межах його категорії.", "explSpecific": "Правильно — «Только автомобилями с автоматической коробкой передач, входящими в категорию его водительского удостоверения». Дозвіл на механічну коробку суперечить обмеженню; виняток лише для автомагістралі — вигадане послаблення."}, {"num": 507, "text": "Разрешено ли водителю-ученику водить автомобиль без сопровождения, если у него есть согласие владельца транспортного средства?", "topic": "Штрафні бали, права та документи", "options": ["Да, если владелец транспортного средства дал свое согласие.", "Да, при условии, что у владельца автомобиля есть действующая страховка.", "Да, если владелец является членом семьи и дал свое согласие.", "Нет, водителю-ученику не разрешается водить автомобиль без сопровождения даже с согласия владельца."], "correct": 3, "expl": "Згода власника транспортного засобу не скасовує обов'язкового супроводу — водій-учень завжди повинен їздити з кваліфікованим супроводжуючим.", "explSpecific": "Правильно — «Нет, водителю-ученику не разрешается водить автомобиль без сопровождения даже с согласия владельца». Наявність згоди власника, дійсної страховки чи родинного зв'язку не скасовує обов'язкової вимоги супроводу."}, {"num": 508, "text": "В случае поломки автомобиля, где водитель должен остановиться?", "topic": "Автомагістраль і тунелі", "options": ["Ближайший съезд с автомагистрали.", "В переулке где возникла проблема.", "Как можно левее.", "Как можно правее."], "correct": 2, "expl": "У разі поломки автомобіля водій повинен зупинитися якомога лівіше — на узбіччі чи крайній лівій смузі, звільняючи проїжджу частину.", "explSpecific": "Правильно — «Как можно левее». «Найближчий з'їзд з автомагістралі» не завжди досяжний вчасно; зупинка «де виникла проблема» чи «якомога правіше» (в бік зустрічного руху) — небезпечні альтернативи."}, {"num": 509, "text": "Если водитель стал участником серьезного столкновения с незастрахованным автомобилистом, в котором никто не пострадал, кому следует сообщить об этом?", "topic": "Штрафні бали, права та документи", "options": ["Ирландская Федерация Страхования.", "Национальная служба выдачи водительских удостоверений (NDLS).", "Страховая компания водителя и Гарда.", "Местное Управление по налогообложению автомобилей."], "correct": 2, "expl": "Про серйозне зіткнення з незастрахованим автомобілістом навіть без постраждалих слід повідомити свою страхову компанію та Гарду.", "explSpecific": "Правильно — «Страховая компания водителя и Гарда». Ірландська федерація страхування, NDLS чи податкове управління автомобілів не є органами, куди слід звертатися в такій ситуації."}, {"num": 510, "text": "Что делать водителю, если он столкнулся с другим транспортным средством, и при этом никто не пострадал?", "topic": "Штрафні бали, права та документи", "options": ["Подать письменный отчет в страховое бюро Ирландии.", "Предоставить свое имя и адрес другому лицу.", "Не обмениваться никакими данными, но сообщить о происшествии в Гарду.", "Обменяться всеми необходимыми данными с другим водителем."], "correct": 3, "expl": "У разі зіткнення без постраждалих водії повинні обмінятися всіма необхідними даними одне з одним.", "explSpecific": "Правильно — «Обменяться всеми необходимыми данными с другим водителем». Письмовий звіт до страхового бюро, надання даних лише про себе чи відмова від обміну даними з повідомленням у Гарду — не відповідають стандартній процедурі."}, {"num": 511, "text": "Что делать водителю, если он оказывается на месте столкновения с транспортным средством, перевозящим опасные материалы?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Связаться с компанией-перевозчиком, которой принадлежит автомобиль.", "Постараться предотвратить дальнейшую утечку опасных материалов, прежде чем поднять тревогу.", "Держаться подальше и позвонить в аварийные службы.", "Попробовать переместить автомобиль в безопасное место."], "correct": 2, "expl": "У разі зіткнення з транспортом, що перевозить небезпечні матеріали, головне правило — не наближатися самостійно, а викликати спеціалізовані аварійні служби, здатні безпечно впоратися з витоком.", "explSpecific": "Правильно — «Держаться подальше и позвонить в аварийные службы». Спроба зв'язатися з перевізником, самостійно зупинити витік чи перемістити автомобіль з небезпечним вантажем підвищують особистий ризик замість зменшення небезпеки."}, {"num": 512, "text": "Что должен делать водитель, если он вовлечен в ДТП, в котором только пострадало только имущество?", "topic": "Статистика ДТП", "options": ["Нет необходимости сообщать об этом в Гарду, если был уведомлен владелец собственности.", "Сообщить об инциденте как владельцу собственности, так и в Гарду в течение 48 часов.", "О происшествии необходимо сообщить в Гарда в течение 10 дней.", "Нет необходимости сообщать об инциденте, если автомобиль не поврежден."], "correct": 0, "expl": "Ці питання ґрунтуються на реальних офіційних звітах про дорожньо-транспортні пригоди в Ірландії (наприклад, дані про вплив алкоголю, стать водіїв, поведінку свідків на місці ДТП). Тут немає логічного виведення відповіді — це конкретні факти зі звітів, які потрібно просто запам'ятати.", "explSpecific": "Правильна відповідь тут — «Нет необходимости сообщать об этом в Гарду, если был уведомлен владелец собственности». Інші варіанти в цьому питанні («Сообщить об инциденте как владельцу собственности, так и в Гарду в течение 48 часов», «О происшествии необходимо сообщить в Гарда в течение 10 дней» та «Нет необходимости сообщать об инциденте, если автомобиль не поврежден») не відповідають цій вимозі й тому неправильні."}, {"num": 513, "text": "Что должен делать водитель, если в результате столкновения пострадал человек?", "topic": "Загальні правила та поведінка на дорозі", "options": ["Переместить жертву на обочину.", "Убрать транспортные средства с дороги, чтобы не создавать препятствий.", "Всегда перемещать жертву и транспортные средства.", "Перемещать жертву только в случае риска пожара или дополнительных травм."], "correct": 3, "expl": "Постраждалого в ДТП не можна переміщувати без потреби — рух може посилити травми, зокрема хребта; переміщення виправдане лише за реальної загрози (пожежа, ризик подальших ушкоджень).", "explSpecific": "Правильно — «Перемещать жертву только в случае риска пожара или дополнительных травм». Переміщення на узбіччя за замовчуванням чи завжди — небезпечна практика; згадка лише про прибирання транспортних засобів не відповідає суті питання."}, {"num": 514, "text": "Какой тип напитка следует дать человеку, получившему травму в результате столкновения?", "topic": "Алкоголь, наркотики, втома водія", "options": ["Холодный напиток.", "Напитки давать нельзя.", "Безалкогольный напиток.", "Горячий напиток."], "correct": 1, "expl": "Алкоголь, наркотики і втома схожі тим, що вони порушують реакцію, оцінку відстані та здатність приймати рішення — причому водій часто не усвідомлює, наскільки сильно він порушений. Тому правильна відповідь завжди на боці обережності: не сідати за кермо, зробити перерву, поступитися керуванням іншому. Для водіїв-учнів і початківців штрафи й дискваліфікація за такі порушення суворіші, ніж для досвідчених водіїв.", "explSpecific": "Правильна відповідь тут — «Напитки давать нельзя». Інші варіанти в цьому питанні («Холодный напиток», «Безалкогольный напиток» та «Горячий напиток») не відповідають цій вимозі й тому неправильні."}, {"num": 515, "text": "Что должен сделать водитель, чтобы помочь человеку, который потерял сознание после столкновения?", "topic": "Загальні правила та поведінка на дорозі", "options": ["Поднять голову человека и удерживать ее в этом положении.", "Стараться согреть человека с помощью одеяла или пальто.", "Попробовать заставить человека выпить что-нибудь теплое.", "Немедленно направить человека в ближайшую больницу."], "correct": 1, "expl": "Людину, яка знепритомніла після зіткнення, важливо зігріти (укрити ковдрою чи одягом) і не намагатися рухати голову чи давати їй щось пити.", "explSpecific": "Правильно — «Стараться согреть человека с помощью одеяла или пальто». Підняття й утримання голови чи спроба напоїти непритомну людину — небезпечні дії; негайне самостійне транспортування без виклику швидкої — не рекомендована перша допомога."}, {"num": 516, "text": "Какова хорошая базовая первая помощь для человека, который получил ожоги?", "topic": "Загальні правила та поведінка на дорозі", "options": ["Нанести смазку на ожог.", "Налить холодную воду на ожог.", "Удалить одежду с места ожога.", "Налить теплую воду на ожог."], "correct": 1, "expl": "Базова перша допомога при опіку — охолодити уражену ділянку прохолодною (не крижаною) водою якомога довше, щоб зменшити глибину пошкодження тканин.", "explSpecific": "Правильно — «Налить холодную воду на ожог». Мастило чи тепла вода погіршують стан опіку; знімання одягу з місця опіку без потреби може додатково пошкодити обпечену шкіру."}, {"num": 517, "text": "Имея дело с жертвами аварии, помните про А В С. Что означает С?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Кашель.", "Кома.", "Сердечный приступ.", "Кровообращение."], "correct": 3, "expl": "У наданні першої допомоги міжнародний принцип ABC означає послідовність перевірки: Airway (дихальні шляхи), Breathing (дихання), Circulation (кровообіг).", "explSpecific": "Правильно — «Кровообращение» (Circulation). «Кашель», «кома» і «серцевий напад» не відповідають жодній літері стандартного протоколу ABC першої допомоги."}, {"num": 518, "text": "С кем в первую очередь следует связаться, если человек получил травму в результате столкновения?", "topic": "Штрафні бали, права та документи", "options": ["С родственниками пострадавшего.", "Со страховой компанией пострадавшего.", "С адвокатом пострадавшего.", "Со службой скорой помощи."], "correct": 3, "expl": "Якщо в результаті зіткнення хтось отримав травму, першочергово слід зв'язатися зі службою швидкої допомоги.", "explSpecific": "Правильно — «Со службой скорой помощи». Зв'язок з родичами, страховою компанією чи адвокатом постраждалого не є першочерговою дією і не рятує здоров'я в критичний момент."}, {"num": 519, "text": "Имея дело с жертвами аварии, помните про А В С. Что означает А?", "topic": "Технічні несправності та аварійні ситуації", "options": ["ДТП.", "Руки.", "Помощь.", "Дыхательные пути"], "correct": 3, "expl": "Перша літера протоколу ABC (Airway) означає перевірку та забезпечення прохідності дихальних шляхів постраждалого — це завжди перший крок.", "explSpecific": "Правильно — «Дыхательные пути» (Airway). «ДТП», «руки» і «допомога» не відповідають жодній стандартній літері протоколу ABC."}, {"num": 520, "text": "Если пострадавший лежит на дороге, когда его следует переместить?", "topic": "Статистика ДТП", "options": ["Сломаны ли у человека кости.", "Нужна ли ему СЛР.", "Есть ли у него кровотечение.", "Холодный ли человек."], "correct": 1, "expl": "Ці питання ґрунтуються на реальних офіційних звітах про дорожньо-транспортні пригоди в Ірландії (наприклад, дані про вплив алкоголю, стать водіїв, поведінку свідків на місці ДТП). Тут немає логічного виведення відповіді — це конкретні факти зі звітів, які потрібно просто запам'ятати.", "explSpecific": "Правильна відповідь тут — «Нужна ли ему СЛР». Інші варіанти в цьому питанні («Сломаны ли у человека кости», «Есть ли у него кровотечение» та «Холодный ли человек») не відповідають цій вимозі й тому неправильні."}, {"num": 521, "text": "При вызове помощи по экстренному телефону на автомагистрали, кому следует звонить?", "topic": "Автомагістраль і тунелі", "options": ["Совет национальной безопасности.", "Управление по безопасности дорожного движения.", "Национальное управление автомобильных дорог.", "Гарда."], "correct": 3, "expl": "Телефонуючи по екстреному телефону на автомагістралі, водій зв'язується з поліцією (Гардою), яка координує допомогу.", "explSpecific": "Правильно — «Гарда». Рада національної безпеки, управління безпеки дорожнього руху чи національне управління автомобільних доріг — не є органами, з якими напряму з'єднує екстрений телефон."}, {"num": 522, "text": "Для того, чтобы сообщить аварийным службам о происшествии, по какому номеру телефона следует позвонить?", "topic": "Технічні несправності та аварійні ситуації", "options": ["112", "555", "199", "911"], "correct": 0, "expl": "В Ірландії, як і в усьому Європейському Союзі, єдиний номер екстрених служб для виклику поліції, швидкої чи пожежних — 112 (паралельно діє і 999).", "explSpecific": "Правильно — «112» — офіційний загальноєвропейський номер екстреної служби. Інші номери (555, 199, 911) не є діючими екстреними номерами в Ірландії."}, {"num": 523, "text": "Какой самый быстрый способ предупредить другой транспорт об аварии?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Использовать аварийные огни.", "Поместить большой объект в центр дороги.", "Позвонить на местную радиостанцию.", "Встать на дорогу и размахивать руками."], "correct": 0, "expl": "Найшвидший і найбезпечніший спосіб попередити інший транспорт про аварію — увімкнути аварійні (сигнальні) вогні власного автомобіля, які видно здалеку.", "explSpecific": "Правильно — «Использовать аварийные огни». Розміщення великого об'єкта на дорозі чи стояння на проїжджій частині, розмахуючи руками, — небезпечні для водія дії; дзвінок на радіостанцію не є швидким способом попередити транспорт, що наближається."}, {"num": 524, "text": "Что должен сделать водитель, чтобы избежать необходимости резкого торможения?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Двигаться держа одну ногу на педали сцепления.", "Двигаться со включенным круиз-контролем", "Смотреть вперед и ожидать, что могут сделать другие.", "Двигаться держа одну ногу на педали тормоза."], "correct": 2, "expl": "Щоб уникнути різкого гальмування, головна навичка водія — завчасно прогнозувати дії інших учасників руху, дивлячись далеко вперед, а не реагувати в останній момент.", "explSpecific": "Правильно — «Смотреть вперед и ожидать, что могут сделать другие». Тримання ноги на педалі зчеплення чи гальма — шкідливі звички; круїз-контроль не звільняє від потреби прогнозувати ситуацію."}, {"num": 525, "text": "Как водитель узнает общую грузоподъемность автомобиля?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Путем проверки мощности двигателя.", "Путем измерения размера багажника.", "Со ссылкой на спецификацию производителя транспортного средства.", "Подсчитав количество сидений."], "correct": 2, "expl": "Загальна максимальна вантажопідйомність автомобіля — це технічна характеристика, встановлена виробником, а не показник, який можна визначити на око чи за іншими непрямими ознаками.", "explSpecific": "Правильно — «Со ссылкой на спецификацию производителя транспортного средства». Потужність двигуна, розмір багажника чи кількість сидінь не є надійними показниками саме вантажопідйомності."}, {"num": 526, "text": "0т чего зависит максимально допустимое тяговое усилие транспортного средства?", "topic": "Причепи, трактори та великогабаритний транспорт", "options": ["Спецификации производителя.", "Сила фаркопа.", "Размер шин на транспортном средстве.", "Совокупный вес автомобиля и его прицепа."], "correct": 0, "expl": "Максимально допустиме тягове зусилля транспортного засобу визначається специфікаціями виробника, а не довільними фізичними параметрами.", "explSpecific": "Правильно — «Спецификации производителя». Сила фаркопа, розмір шин чи сукупна вага автомобіля з причепом — це супутні фактори, але саме офіційні специфікації виробника визначають межу."}, {"num": 527, "text": "Какое влияние оказывает перегрузка транспортного средства на сцепление с дорогой?", "topic": "Загальні правила та поведінка на дорозі", "options": ["Нагрузка может усложнить управление транспортным средством.", "Нагрузка не может усложнить управление транспортным средством.", "Нагрузка может улучшить управление транспортным средством.", "Нагрузка влияет лишь на покрытие дороги."], "correct": 0, "expl": "Перевантаження автомобіля змінює його вагу й розподіл ваги, ускладнюючи керування — гальмування, повороти й стійкість.", "explSpecific": "Правильно — «Нагрузка может усложнить управление транспортным средством». Твердження про відсутність впливу чи покращення керування прямо суперечать фізиці збільшеної маси."}, {"num": 528, "text": "Каков будет эффект перегрузки транспортного средства пассажирами или товарами?", "topic": "Швидкісний режим", "options": ["Не будет иметь никакого эффекта, если скорость уменьшена.", "Уменьшит способность водителя управлять транспортным средством.", "Улучшит способность автомобиля сохранять заданное направление движения.", "Перегрузка не снизит возможности управления транспортным средством."], "correct": 1, "expl": "Перевантаження автомобіля пасажирами чи вантажем знижує здатність водія керувати транспортним засобом, впливаючи на гальмування, повороти й стійкість.", "explSpecific": "Правильно — «Уменьшит способность водителя управлять транспортным средством». Твердження про відсутність ефекту при зниженій швидкості чи покращення утримання заданого напрямку прямо суперечать реальному негативному впливу перевантаження."}, {"num": 529, "text": "Какое влияние может оказать неравномерно распределенная нагрузка на автомобиль?", "topic": "Загальні правила та поведінка на дорозі", "options": ["Она может привести к неустойчивости автомобиля при повороте.", "Она может привести к скольжению сцепления при ускорении.", "Она может привести к перегреву транспортного средства.", "Она может привести к перегреву коробки передач."], "correct": 0, "expl": "Нерівномірно розподілений вантаж зміщує центр ваги автомобіля вбік, через що на поворотах машина стає менш стійкою і схильною до перекидання чи заносу.", "explSpecific": "Правильно — «Она может привести к неустойчивости автомобиля при повороте». Прослизання зчеплення при прискоренні чи перегрів двигуна/коробки передач не є типовими наслідками нерівномірного розподілу вантажу."}, {"num": 530, "text": "К чему ведет неправильная регулировка фар?", "topic": "Дитячі крісла та ремені безпеки", "options": ["Это может привести к сокращению срока службы батареи.", "К ослеплению встречных водителей.", "К возгоранию.", "К преждевременному износу ламп."], "correct": 1, "expl": "Ремінь безпеки і дитяче крісло працюють за одним принципом — розподілити силу удару по найміцніших частинах тіла і не дати людині вилетіти з салону чи вдаритись об внутрішні поверхні авто. Відповідальність за пристібання дітей молодшого віку лежить на водієві, а не на самій дитині чи батьках, які не за кермом — це і пояснює логіку відповідей у таких питаннях.", "explSpecific": "Правильна відповідь тут — «К ослеплению встречных водителей». Інші варіанти в цьому питанні («Это может привести к сокращению срока службы батареи», «К возгоранию» та «К преждевременному износу ламп») не відповідають цій вимозі й тому неправильні."}, {"num": 531, "text": "Почему важно обеспечить правильную регулировку фар автомобиля?", "topic": "Загальні правила та поведінка на дорозі", "options": ["Чтобы уменьшить расход батареи.", "Чтобы водитель мог хорошо видеть.", "Чтобы водитель мог двигаться быстрее в темноте.", "Чтобы увеличить срок службы фар."], "correct": 1, "expl": "Правильно відрегульовані фари забезпечують водієві максимальну видимість дороги вночі, не засліплюючи при цьому зустрічний транспорт.", "explSpecific": "Правильно — «Чтобы водитель мог хорошо видеть». Економія заряду батареї, можливість їхати швидше в темряві чи довговічність ламп — не є головною метою правильного регулювання фар."}, {"num": 532, "text": "Каков вероятный эффект любопытства автомобилистов на месте ДТП?", "topic": "Статистика ДТП", "options": ["Это может вызвать дополнительные происшествия, поскольку водители отвлекаются.", "Это позволяет транспорту изменить курс без дополнительного внимания.", "Это позволяет транспорту изменить скорость без дополнительного внимания.", "Это может увеличить транспортный поток возле места ДТП"], "correct": 0, "expl": "Ці питання ґрунтуються на реальних офіційних звітах про дорожньо-транспортні пригоди в Ірландії (наприклад, дані про вплив алкоголю, стать водіїв, поведінку свідків на місці ДТП). Тут немає логічного виведення відповіді — це конкретні факти зі звітів, які потрібно просто запам'ятати.", "explSpecific": "Правильна відповідь тут — «Это может вызвать дополнительные происшествия, поскольку водители отвлекаются». Інші варіанти в цьому питанні («Это позволяет транспорту изменить курс без дополнительного внимания», «Это позволяет транспорту изменить скорость без дополнительного внимания» та «Это может увеличить транспортный поток возле места ДТП») не відповідають цій вимозі й тому неправильні."}, {"num": 533, "text": "Какое минимальное количество штрафных баллов предусмотрено для водителя-ученика за не отображение таблички с буквой \"L\" как на передней, так и на задней части автомобиля?", "topic": "Штрафні бали, права та документи", "options": ["1 штрафной балл.", "3 штрафной балла.", "4 штрафной балла.", "2 штрафной балла."], "correct": 3, "expl": "За невідображення таблички «L» спереду і ззаду автомобіля водій-учень отримує мінімум 2 штрафних бали.", "explSpecific": "Правильно — «2 штрафной балла». 1, 3 чи 4 бали не відповідають встановленому мінімуму за це конкретне порушення."}, {"num": 534, "text": "B общем, как часто следует проверять огни автомобиля?", "topic": "Загальні правила та поведінка на дорозі", "options": ["В самые большие интервалы между техническими обслуживаниями.", "Ежедневно перед поездкой.", "В самые малые интервалы между техническими обслуживаниями.", "Перед зимним сезоном."], "correct": 1, "expl": "Справність освітлення автомобіля варто перевіряти щодня перед поїздкою, а не лише під час планового технічного обслуговування, оскільки лампочка може перегоріти будь-коли.", "explSpecific": "Правильно — «Ежедневно перед поездкой». Прив'язка лише до інтервалів технічного обслуговування чи сезону залишає великі періоди, коли несправність освітлення може залишитися непоміченою."}, {"num": 535, "text": "Какое влияние может иметь сломанный рассеиватель на фары?", "topic": "Погодні умови та видимість", "options": ["Это может привести к перегреву лампы.", "Это уменьшит и исказит луч.", "Это может привести к перегоранию других ламп, если дефект не будет немедленно устранен.", "Это может увеличить яркость луча в другой фаре."], "correct": 1, "expl": "Пошкоджений розсіювач фари змінює форму й напрямок світлового пучка, через що освітлення дороги стає гіршим і спотвореним.", "explSpecific": "Правильно — «Это уменьшит и исказит луч». Перегрів лампи, перегорання інших ламп чи збільшення яскравості іншої фари — не є типовими прямими наслідками саме пошкодженого розсіювача."}, {"num": 536, "text": "Водитель хочет отправиться в поездку ночью, но лампа фары ближнего света с правой стороны перегорает. Как водителю следует поступить?", "topic": "Погодні умови та видимість", "options": ["Не отправляться в поездку не заменив лампу.", "Временно заменить ее на лампу с левой стороны.", "Отправляться в путь со включенными аварийными огнями.", "Временно заменить ее на лампу стоп-сигнала."], "correct": 0, "expl": "Якщо перегоріла лампа фари перед нічною поїздкою, правильна дія — замінити лампу перед виїздом, а не імпровізувати з іншими лампами чи аварійними вогнями.", "explSpecific": "Правильно — «Не отправляться в поездку не заменив лампу». Тимчасова заміна лампою з іншого боку чи від стоп-сигналу — технічно неправильна імпровізація."}, {"num": 537, "text": "Как водителю узнать, что лампочка стоп-сигнала не работает?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Они заметит, что педаль тормоза становится мягче под давлением.", "Они заметит, что педаль тормоза становится более твердой под давлением.", "Стоя в задней части автомобиля, пока другой человек за рулем автомобиля включает габаритные огни.", "Стоя в задней части автомобиля проверить, включены ли стоп-сигналы, пока другой человек нажимает на педаль тормоза."], "correct": 3, "expl": "Стоп-сигнали розташовані ззаду й не видно з місця водія — щоб перевірити їхню роботу, потрібна друга людина, яка натисне гальмо, поки водій (чи хтось інший) дивиться ззаду.", "explSpecific": "Правильно — «Стоя в задней части автомобиля проверить, включены ли стоп-сигналы, пока другой человек нажимает на педаль тормоза». Відчуття педалі гальма не має стосунку до роботи лампочок; перевірка габаритних, а не стоп-сигналів, не відповідає суті питання."}, {"num": 538, "text": "Разрешается ли управлять транспортным средством на дороге общего пользования, когда стоп-сигналы не работают?", "topic": "Загальні правила та поведінка на дорозі", "options": ["Да, во время включения освещения.", "Нет, если только он не едет по застроенной территории.", "Нет, не разрешается.", "Да, во время выключения освещения."], "correct": 2, "expl": "Керування автомобілем з несправними стоп-сигналами заборонено завжди, оскільки вони критично важливі для безпеки — попереджають транспорт позаду про гальмування.", "explSpecific": "Правильно — «Нет, не разрешается». Прив'язка дозволу до включеного чи вимкненого освітлення чи до типу місцевості — вигадані, не передбачені правилом винятки."}, {"num": 539, "text": "Что означает этот световой сигнал?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Уровень масла слишком низкий.", "Батарея не заряжается.", "Коробка передач перегревается", "Двигатель перегревается."], "correct": 1, "expl": "Індикатор у формі акумулятора на панелі приладів засвічується, коли система заряджання (генератор) не поповнює заряд акумулятора під час роботи двигуна.", "explSpecific": "Правильно — «Батарея не заряжается». «Рівень масла», «перегрів коробки передач» і «перегрів двигуна» позначаються geть іншими за формою піктограмами на панелі приладів.", "img": "q539.png"}, {"num": 540, "text": "Что означает этот световой сигнал?", "topic": "Погодні умови та видимість", "options": ["Фары дальнего света включены.", "Фонарь заднего хода включен.", "Свет номерного знака неисправен.", "Фары дальнего света следует переключить."], "correct": 0, "expl": "Синій індикатор на панелі приладів у формі фар з горизонтальними променями сигналізує, що увімкнено дальнє світло фар.", "explSpecific": "Правильно — «Фары дальнего света включены». «Фонарь заднего хода» і «неисправность света номерного знака» позначаються geть іншими за формою й кольором індикаторами.", "img": "q540.png"}, {"num": 541, "text": "Что означает этот световой сигнал?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Низкий уровень охлаждающей жидкости двигателя.", "Низкий уровень моторного масла.", "Низкий уровень жидкости в аккумуляторе.", "Низкий уровень тормозной жидкости."], "correct": 1, "expl": "Піктограма маслянки на панелі приладів означає низький рівень моторного масла — потребу перевірити й долити мастило.", "explSpecific": "Правильно — «Низкий уровень моторного масла» (піктограма маслянки). «Охолоджуюча рідина», «рідина в акумуляторі» та «гальмівна рідина» позначаються geть іншими символами.", "img": "q541.png"}, {"num": 542, "text": "Что означает этот световой сигнал?", "topic": "Погодні умови та видимість", "options": ["Лампа фары ближнего света перегорела.", "Указатель направления включен.", "Лампа стоп-сигнала перегорела.", "Правый противотуманный свет включен."], "correct": 1, "expl": "Зелений мигаючий індикатор-стрілка на панелі приладів сигналізує про активний покажчик повороту (лівий чи правий).", "explSpecific": "Правильно — «Указатель направления включен». «Лампа ближнього світла перегоріла» і «лампа стоп-сигналу перегоріла» позначаються geть іншими символами; «правий протитуманний увімкнено» має власну окрему піктограму.", "img": "q542.png"}, {"num": 543, "text": "Что делать водителю, если во время вождения на приборной панели его автомобиля загорается сигнальная лампа системы?", "topic": "Загальні правила та поведінка на дорозі", "options": ["Продолжить движение и прислушаться к любым необычным звукам.", "Продолжить движение, и посмотреть, не погаснет ли свет.", "Остановиться и выяснить, в чем проблема.", "Продолжить движение и узнать в чем проблема позже."], "correct": 2, "expl": "Коли на панелі приладів засвічується попереджувальна лампа, водій повинен зупинитися і з'ясувати причину, а не продовжувати їхати, сподіваючись, що проблема зникне сама.", "explSpecific": "Правильно — «Остановиться и выяснить, в чем проблема». Продовження руху з прислуховуванням до звуків чи очікуванням, що лампа згасне, відкладає реакцію на потенційно серйозну несправність."}, {"num": 544, "text": "Что делать водителю, если на приборной панели его автомобиля загорается красная сигнальная лампа системы?", "topic": "Загальні правила та поведінка на дорозі", "options": ["Отправиться в ближайший гараж и проверить, в чем проблема.", "Остановиться и выяснить, в чем проблема.", "Продолжить движение и прислушаться к любым необычным звукам.", "Продолжить движение, и посмотреть, не погаснет ли свет."], "correct": 1, "expl": "Червона попереджувальна лампа (на відміну від жовтої/бурштинової) сигналізує про серйознішу, часто критичну несправність, що вимагає негайної зупинки.", "explSpecific": "Правильно — «Остановиться и выяснить, в чем проблема». Поїздка до найближчого гаража своїм ходом чи продовження руху ризикують серйозним пошкодженням автомобіля саме через терміновість червоного сигналу."}, {"num": 545, "text": "Каково назначение красных отражателей в задней части автомобиля?", "topic": "Пішоходи, велосипедисти, мотоциклісти", "options": ["Они отражают свет ночью, чтобы другие участники дорожного движения знали о транспортном средстве.", "Они предупреждают водителя сзади о необходимости переключиться на дальний свет.", "Они предупреждают пешеходов о местонахождении автомобиля.", "Они служат заменой на случай неисправности стоп-сигнала."], "correct": 0, "expl": "Червоні світловідбивачі ззаду автомобіля пасивно відбивають світло фар транспорту позаду вночі, роблячи автомобіль видимим навіть без власного джерела світла.", "explSpecific": "Правильно — «Они отражают свет ночью, чтобы другие участники дорожного движения знали о транспортном средстве». Попередження про перемикання на дальнє світло чи заміна стоп-сигналу — не є функцією пасивних відбивачів."}, {"num": 546, "text": "Что это может означать быстрый щелкающий звук при нажатии на индикаторный выключатель?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Регулятор напряжения работает некорректно.", "Возможно, перегорела лампочка индикатора.", "Неисправен выключатель аварийной сигнализации.", "Предупреждающие огни включены."], "correct": 1, "expl": "Швидке клацання поворотника (частіше нормального ритму) — класична ознака перегорілої лампочки одного з покажчиків повороту в реле-переривнику.", "explSpecific": "Правильно — «Возможно, перегорела лампочка индикатора». Несправність регулятора напруги, вимикача аварійної сигналізації чи включені попереджувальні вогні не пов'язані саме зі зміною частоти клацання поворотника."}, {"num": 547, "text": "Какова функция антиблокировочной тормозной системы (ABS)?", "topic": "Технічні несправності та аварійні ситуації", "options": ["ABS предотвращает блокировку колес в условиях жесткого торможения.", "ABS раскрывает подушки безопасности во время столкновения.", "ABS отображает название радиостанции, играющей на автомобильном радиоприемнике.", "ABS блокирует тормоза, чтобы предотвратить занос во время резкого торможения."], "correct": 0, "expl": "Антиблокувальна система гальм (ABS) запобігає повній блокуванню коліс під час різкого гальмування, зберігаючи керованість автомобіля.", "explSpecific": "Правильно — «ABS предотвращает блокировку колес в условиях жесткого торможения». Подушки безпеки, назва радіостанції чи навмисне блокування коліс не мають жодного стосунку до функції ABS."}, {"num": 548, "text": "Что означает, если педаль тормоза транспортного средства мягко нажимается или пружинит?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Неисправность в системе тормозной жидкости.", "Изношены тормозные колодки.", "Неисправность в кабеле ручного тормоза.", "Стояночный тормоз включен."], "correct": 0, "expl": "М'яка чи пружна педаль гальма зазвичай свідчить про повітря в гальмівній системі чи витік гальмівної рідини — тобто несправність саме гідравлічної частини гальм.", "explSpecific": "Правильно — «Неисправность в системе тормозной жидкости». Знос колодок зазвичай проявляється інакше (вищий хід педалі чи скрип); несправність тросика ручного гальма чи ввімкнений стоянковий гальмо не впливають на м'якість ножної педалі."}, {"num": 549, "text": "По каким признакам водитель может заподозрить, что уровень тормозной жидкости в его автомобиле низкий?", "topic": "Технічні несправності та аварійні ситуації", "options": ["На тормоза сложно нажимать.", "Тормоза кажутся мягкими и пружинят.", "Необычайно резкое нажатие педали тормоза.", "Тормоза отпускаются дольше, чем обычно."], "correct": 1, "expl": "Низький рівень гальмівної рідини часто проявляється саме як м'яка, пружна педаль гальма через наявність повітря в системі.", "explSpecific": "Правильно — «Тормоза кажутся мягкими и пружинят». «Складно натискати» і «незвично різке натискання» описують інші симптоми; «гальма відпускаються довше» не є типовою ознакою саме низького рівня рідини."}, {"num": 550, "text": "На какой срок вождение будет запрещено водителю- ученику, который получает 7 штрафных баллов в течение 36 месяцев (три года)?", "topic": "Штрафні бали, права та документи", "options": ["6 месяцев.", "9 месяцев.", "3 месяца.", "12 месяцев."], "correct": 0, "expl": "Водій-учень, який набирає 7 штрафних балів протягом 36 місяців, отримує заборону на керування терміном 6 місяців.", "explSpecific": "Правильно — «6 месяцев». 3, 9 чи 12 місяців не відповідають встановленому терміну заборони саме для водіїв-учнів за цей поріг балів."}, {"num": 551, "text": "Что является наиболее вероятной причиной скрипа при нажатии на педаль тормоза?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Износ тормозных накладок или колодок.", "Одна из передних шин спущена.", "Тормозные колодки мокрые.", "Одна из задних шин спущена."], "correct": 0, "expl": "Скрипучий звук при натисканні на гальмо — класична ознака зношених гальмівних колодок, які потребують заміни.", "explSpecific": "Правильно — «Износ тормозных накладок или колодок». Спущена шина (передня чи задня) не спричиняє скрип при натисканні педалі гальма — це geть інша, не пов'язана з гальмівною системою несправність."}, {"num": 552, "text": "Что может указывать на проблему с тормозной системой автомобиля?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Стояночный тормоз автомобиля более эффективен.", "Повреждение подвески автомобиля.", "Снижение потребления топлива.", "Изменение тормозной способности автомобиля."], "correct": 3, "expl": "Проблему з гальмівною системою найчастіше виявляють саме через зміну поведінки гальм — інший хід педалі, знижену ефективність чи нерівномірне гальмування.", "explSpecific": "Правильно — «Изменение тормозной способности автомобиля». «Більш ефективний стоянковий гальмо», «пошкодження підвіски» і «зниження витрати палива» не є типовими чи прямими ознаками проблем саме з гальмівною системою."}, {"num": 553, "text": "Что следует знать водителю при управлении автомобилем с автоматической коробкой передач?", "topic": "Автомагістраль і тунелі", "options": ["Что коробка передач может перегреться при движении на низкой передаче.", "Что тормозная мощность двигателя уменьшается.", "Это вождение по автомагистрали не допускается.", "Что пробуксовка возникает чаще."], "correct": 1, "expl": "Керуючи автомобілем з автоматичною коробкою передач, водій повинен пам'ятати, що гальмування двигуном слабше, ніж на механічній коробці.", "explSpecific": "Правильно — «Что тормозная мощность двигателя уменьшается». Перегрів коробки на низькій передачі, заборона їзди автомагістраллю чи частіша пробуксовка — вигадані чи невірні твердження."}, {"num": 554, "text": "Как влияет автоматическая коробка передач на мощность торможения двигателем?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Снижает ее.", "Передает тормозную способность на ручной тормоз.", "Передает тормозную способность на все колеса.", "Повышает ее."], "correct": 0, "expl": "Автоматична коробка передач зазвичай забезпечує слабше гальмування двигуном порівняно з механічною, оскільки трансмісія менш жорстко зв'язана з колесами на нейтральних чи проміжних режимах.", "explSpecific": "Правильно — «Снижает ее». Варіанти про передачу гальмівної здатності на ручний гальмо чи всі колеса — технічно необґрунтовані вигадки; «підвищує» — прямо протилежний, невірний висновок."}, {"num": 555, "text": "Что этот прибор показывает?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Уровень топлива.", "Уровень масла.", "Число оборотов коробки передач.", "Число оборотов двигателя."], "correct": 3, "expl": "Круговий прилад зі шкалою у сотнях обертів і стрілкою — тахометр, який показує поточну частоту обертання двигуна за хвилину.", "explSpecific": "Правильно — «Число оборотов двигателя». Рівень палива чи масла показують окремі прилади з іншою шкалою; «оберти коробки передач» не є показником, який відображає тахометр.", "img": "q555.png"}, {"num": 556, "text": "чем предоставляет информацию счетчик оборотов?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Число оборотов двигателя.", "Обороты колес.", "Обороты коробки передач.", "Обороты обогревателя-вентилятора."], "correct": 0, "expl": "Тахометр (лічильник обертів) показує кількість обертів двигуна за хвилину, допомагаючи водію обирати момент перемикання передач.", "explSpecific": "Правильно — «Число оборотов двигателя». Оберти коліс, коробки передач чи вентилятора обігрівача показуються geть іншими приладами, не тахометром.", "img": "q556.png"}, {"num": 557, "text": "Если во время движения водитель замечает, что мощность двигателя ниже нормальной, что ему следует делать?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Обратиться к специалисту.", "Перейти на другое топливо.", "Заменить масляный фильтр двигателя.", "Отрегулировать механизм контроля топливной смеси."], "correct": 0, "expl": "Якщо потужність двигуна відчутно нижча за нормальну, це ознака технічної несправності, яку має діагностувати кваліфікований спеціаліст, а не сам водій.", "explSpecific": "Правильно — «Обратиться к специалисту». Самостійна зміна палива, заміна масляного фільтра чи регулювання паливної суміші без діагностики не гарантують усунення справжньої причини несправності."}, {"num": 558, "text": "Какова цель моторного масла?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Смазывает тормозную систему.", "Смазывает выхлопную систему.", "Смазывает двигатель.", "Смазывает колесные подшипники."], "correct": 2, "expl": "Основне призначення моторного масла — змащувати рухомі частини двигуна, зменшуючи тертя й знос металевих деталей.", "explSpecific": "Правильно — «Смазывает двигатель». Гальмівна, вихлопна системи й колісні підшипники мають власні окремі мастильні матеріали, не пов'язані з моторним маслом."}, {"num": 559, "text": "Если датчик давления масла показывает небольшое давление или вообще не показывает его, или загорается сигнальная лампа, в чем может быть проблема?", "topic": "Загальні правила та поведінка на дорозі", "options": ["Уровень масла слишком высокий.", "Масло слишком густое.", "Уровень масла слишком низкий.", "Масло слишком холодное."], "correct": 2, "expl": "Низький чи відсутній тиск масла (за показником датчика чи спалахом лампи) найчастіше свідчить про недостатній рівень моторного масла в системі.", "explSpecific": "Правильно — «Уровень масла слишком низкий». Зависокий рівень масла, надто густе чи холодне масло — менш поширені й менш прямі причини низького показника тиску на датчику."}, {"num": 560, "text": "Что может произойти в случае несвоевременной замены моторного масла?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Детали двигателя могут подвергаться повышенному износу.", "Потребление топлива автомобилем может повыситься.", "Потребление топлива автомобилем может снизиться.", "Двигатель может перегреться."], "correct": 0, "expl": "Несвоєчасна заміна моторного масла призводить до втрати його мастильних властивостей, через що деталі двигуна труться одна об одну сильніше і швидше зношуються.", "explSpecific": "Правильно — «Детали двигателя могут подвергаться повышенному износу». Зміна витрати палива не головний і не прямий наслідок; перегрів двигуна можливий, але вторинний ефект, тоді як підвищений знос — пряма й основна причина регулярної заміни."}, {"num": 561, "text": "Если автомобиль движется с низким давлением масла, как это влияет на его двигатель?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Это повышает потребление топлива.", "Это увеличивает эффективность топлива.", "Это увеличивает износ двигателя.", "Это увеличивает выбросы выхлопных газов."], "correct": 2, "expl": "Низький тиск моторного масла означає недостатнє змащення деталей двигуна під навантаженням, що прискорює їхній знос.", "explSpecific": "Правильно — «Это увеличивает износ двигателя». Підвищення витрати чи ефективності палива й зростання викидів вихлопних газів не є прямим і головним наслідком саме низького тиску масла."}, {"num": 562, "text": "Если масломер показывает низкое давление масла или загорается красная сигнальная лампочка давления масла, что следует делать водителю?", "topic": "Паркування та зупинка", "options": ["Двигаться на более низких скоростях, пока не пополнит уровень масла.", "Двигаться на пониженной передаче, пока не пополнит уровень масла.", "Двигаться в более быстром темпе, чтобы добраться до места назначения до того, как масло закончится.", "Доехать до безопасного места, остановить автомобиль и проверить уровень масла."], "correct": 3, "expl": "Якщо манометр показує низький тиск масла чи горить червона лампа, водій повинен доїхати до безпечного місця, зупинитися і перевірити рівень масла, а не продовжувати їхати.", "explSpecific": "Правильно — «Доехать до безопасного места, остановить автомобиль и проверить уровень масла». Продовження руху на нижчій швидкості чи передачі ризикує серйозним пошкодженням двигуна через недостатнє змащення."}, {"num": 563, "text": "Что должен сделать водитель прежде чем проверить уровень моторного масла в автомобиле?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Убедиться, что двигатель включен и горячий.", "Убедиться, что двигатель работает.", "Убедиться, что двигатель выключен и холодный.", "Убедиться, что автомобиль находится на пониженной передаче."], "correct": 2, "expl": "Рівень моторного масла коректно вимірюється тільки коли двигун вимкнений і масло встигло стекти назад у піддон, інакше показник щупа буде неточним.", "explSpecific": "Правильно — «Убедиться, что двигатель выключен и холодный». Перевірка на увімкненому чи щойно вимкненому гарячому двигуні дає хибний, завищений чи занижений результат; передача, на якій стоїть авто, не впливає на рівень масла в піддоні."}, {"num": 564, "text": "Какой штраф предусмотрен для владельца транспортного средства, который позволяет водителю-ученику вести свое транспортное средство без сопровождения?", "topic": "Штрафні бали, права та документи", "options": ["Лишение водительских прав.", "Штраф в размере 2000 евро.", "2 штрафных балла.", "Арест транспортного средства."], "correct": 3, "expl": "Власник транспортного засобу, який дозволяє водієві-учню керувати автомобілем без супроводу, ризикує арештом (вилученням) транспортного засобу.", "explSpecific": "Правильно — «Арест транспортного средства». Позбавлення прав, штраф 2000 євро чи штрафні бали стосуються самого водія-учня, а не покарання власника."}, {"num": 565, "text": "Что должен делать водитель, если во время вождения почувствует запах топлива.", "topic": "Паркування та зупинка", "options": ["Остановиться в безопасном месте и осмотреть автомобиль.", "Снизить скорость.", "Открыть окна и продолжать движение.", "Включить вентилятор, чтобы очистить воздух."], "correct": 0, "expl": "Відчувши запах палива під час руху, водій повинен негайно зупинитися в безпечному місці й оглянути автомобіль, оскільки це може свідчити про витік і ризик пожежі.", "explSpecific": "Правильно — «Остановиться в безопасном месте и осмотреть автомобиль». Просте зниження швидкості, відкриття вікон із продовженням руху чи вмикання вентилятора — недостатні заходи для потенційно небезпечної ситуації з витоком палива."}, {"num": 566, "text": "Что означает сигнальная лампа и/или красная зона на указателе уровня топлива?", "topic": "Загальні правила та поведінка на дорозі", "options": ["Низкий уровень топлива в баке.", "Топливный бак переполнен.", "Утечка в топливной системе.", "В баке есть этилированное топливо."], "correct": 0, "expl": "Попереджувальна лампа чи червона зона на покажчику рівня палива сигналізує про наближення палива до критично низького рівня в баку.", "explSpecific": "Правильно — «Низкий уровень топлива в баке». Переповнення бака, витік у паливній системі чи наявність етилованого палива позначаються geть іншими, окремими індикаторами."}, {"num": 567, "text": "Когда рекомендуется использовать охлаждающую жидкость?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Только летом.", "Только в бензиновых двигателях.", "Круглый год.", "Только зимой."], "correct": 2, "expl": "Охолоджуюча рідина потрібна двигуну цілий рік — влітку вона відводить надлишкове тепло, взимку захищає систему охолодження від замерзання.", "explSpecific": "Правильно — «Круглый год». «Тільки влітку» чи «тільки взимку» описують лише одну з двох функцій рідини, ігноруючи іншу; прив'язка виключно до бензинових двигунів невірна, оскільки дизельні двигуни так само потребують охолодження."}, {"num": 568, "text": "Как необходимо действовать, если во время вождения водитель замечает красный сигнал на указателе температуры автомобиля.", "topic": "Загальні правила та поведінка на дорозі", "options": ["Остановиться в безопасном месте и попробовать решить проблему.", "Доехать до ближайшей СТО и долить воду в радиатор.", "Не продолжать движение, не добавив в охлаждающую жидкость анти- парафиновую присадку.", "Снять крышку с радиатора и проверить на утечку."], "correct": 0, "expl": "Червоний сигнал на покажчику температури означає перегрів двигуна — водій повинен негайно зупинитися в безпечному місці, а не продовжувати їхати чи відкривати гарячий радіатор одразу.", "explSpecific": "Правильно — «Остановиться в безопасном месте и попробовать решить проблему». Продовження руху до СТО з перегрітим двигуном ризикує серйозним пошкодженням; зняття кришки з гарячого радіатора небезпечне."}, {"num": 569, "text": "Что должен делать водитель если он заметит пар из моторного отсека?", "topic": "Швидкісний режим", "options": ["Немедленно долить антифриз.", "Увеличить скорость, чтобы увеличить поток воздуха в моторный отсек.", "Снять крышку заливной горловины с бутылки с охлаждающей жидкостью.", "Остановиться в безопасном месте и выяснить причину."], "correct": 3, "expl": "Побачивши пару з підкапотного простору, водій повинен негайно зупинитися в безпечному місці й з'ясувати причину, а не продовжувати рух чи діяти навмання.", "explSpecific": "Правильно — «Остановиться в безопасном месте и выяснить причину». Негайне доливання антифризу чи зняття кришки з гарячої системи охолодження небезпечні (ризик опіку парою); збільшення швидкості для покращення потоку повітря лише посилює перегрів."}, {"num": 570, "text": "Если водитель замечает, что на конструкционных частях кузова автомобиля появилась ржавчина, что ему следует делать?", "topic": "Загальні правила та поведінка на дорозі", "options": ["Обработать область смазкой и закрасить ее.", "Нанести на него краску того же цвета.", "Зачистить место наждачной бумагой и высушить пораженный участок.", "Обратиться за ремонтом к специалисту."], "correct": 3, "expl": "Іржа на конструкційних (несучих) частинах кузова автомобіля впливає на структурну міцність і безпеку, тому таку проблему має усувати кваліфікований спеціаліст, а не сам водій.", "explSpecific": "Правильно — «Обратиться за ремонтом к специалисту». Самостійне змащування, фарбування чи зачищення наждаком — поверхневі дії, які не відновлюють структурну міцність ушкодженого металу."}, {"num": 571, "text": "Какое влияние может оказать изношенный амортизатор на автомобиль?", "topic": "Загальні правила та поведінка на дорозі", "options": ["Может привести к короткому замыканию.", "Может привести к \"дрожанию\" автомобиля.", "Может привести к срабатыванию подушек безопасности.", "Может увеличить потребление топлива."], "correct": 1, "expl": "Зношений амортизатор гірше гасить коливання підвіски, через що автомобіль починає «тремтіти» чи розгойдуватися на нерівностях і після них.", "explSpecific": "Правильно — «Может привести к 'дрожанию' автомобиля». Коротке замикання, спрацювання подушок безпеки чи підвищена витрата палива не є типовими наслідками зношеного амортизатора."}, {"num": 572, "text": "К чему может привести разряженный аккумулятор автомобиля?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Двигатель не заводится.", "Аккумулятор следует заменить", "Кислота из аккумулятора вытечет в двигатель.", "Следует заменить лампочки головного освещения."], "correct": 0, "expl": "Розряджений акумулятор не може забезпечити достатній струм для стартера, тому найпряміший і найпоширеніший наслідок — двигун просто не заводиться.", "explSpecific": "Правильно — «Двигатель не заводится». Необхідність заміни акумулятора чи ламп фар — можливі, але не обов'язкові чи не прямі наслідки; витік кислоти в двигун не є типовим результатом звичайного розряду."}, {"num": 573, "text": "Какова основная цель аккумулятора, установленного на бензиновом или дизельном автомобиле?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Торможение.", "Снижение потребления топлива.", "Подача тепла в двигатель.", "Запуск двигателя."], "correct": 3, "expl": "Основне призначення акумулятора на автомобілі з двигуном внутрішнього згоряння — подати достатній струм на стартер для запуску двигуна.", "explSpecific": "Правильно — «Запуск двигателя». Гальмування, зниження витрати палива чи подача тепла в двигун не є функціями акумулятора — цим займаються геть інші системи автомобіля."}, {"num": 574, "text": "Какое влияние оказывает слабый аккумулятор на ходовые качества автомобиля?", "topic": "Погодні умови та видимість", "options": ["Фары не будут работать.", "Ускорение в гору будет уменьшено.", "Не будет иметь никакого эффекта.", "Топливо будет гореть менее эффективно."], "correct": 2, "expl": "Слабкий акумулятор насамперед впливає на запуск двигуна; коли двигун вже працює, живлення забезпечує генератор, тому на самі ходові якості автомобіля слабкий акумулятор під час руху не впливає.", "explSpecific": "Правильно — «Не будет иметь никакого эффекта» (на ходові якості під час руху). Твердження про непрацюючі фари, зменшене прискорення чи менш ефективне згоряння палива — не є прямими наслідками слабкого акумулятора під час руху зі справним генератором."}, {"num": 575, "text": "Что должен видеть водитель в зеркалах автомобиля, когда они правильно отрегулированы?", "topic": "Загальні правила та поведінка на дорозі", "options": ["Область позади и с каждой стороны автомобиля.", "Пассажирский салон автомобиля.", "Положение всех колес.", "Положение левосторонних колес."], "correct": 0, "expl": "Правильно відрегульовані дзеркала мають показувати водієві простір позаду і з обох боків автомобіля, мінімізуючи сліпі зони.", "explSpecific": "Правильно — «Область позади и с каждой стороны автомобиля». Огляд пасажирського салону чи положення коліс — не є функцією зовнішніх чи внутрішнього дзеркала."}, {"num": 576, "text": "Что должен видеть водитель в наружных зеркалах автомобиля, когда они правильно отрегулированы?", "topic": "Загальні правила та поведінка на дорозі", "options": ["Только стороны автомобиля.", "Только заднюю часть автомобиля.", "Область по сторонам автомобиля.", "60% под углом к автомобилю и 40% - к дороге."], "correct": 2, "expl": "Зовнішні бокові дзеркала налаштовують так, щоб бачити простір збоку від автомобіля, доповнюючи огляд внутрішнього дзеркала, яке показує пряму зону позаду.", "explSpecific": "Правильно — «Область по сторонам автомобиля». Показ лише самих боків машини чи лише задньої частини не відповідає призначенню зовнішніх дзеркал; конкретна пропорція «60/40» — вигадана."}, {"num": 577, "text": "Наружные зеркала автомобиля покрыты грязью и пылью. Как водителю следует поступить?", "topic": "Загальні правила та поведінка на дорозі", "options": ["Продолжить движение и очистить их доехав до места назначения.", "Езжайте в потоке другого транспорта, так как это в конечном итоге очистит зеркала.", "Наклонить зеркала вперед, чтобы очистить их.", "Протереть их тряпкой или салфеткой перед началом путешествия."], "correct": 3, "expl": "Брудні чи запилені дзеркала суттєво знижують огляд, тому їх слід протерти перед початком поїздки, а не сподіватися, що вони самоочистяться в дорозі.", "explSpecific": "Правильно — «Протереть их тряпкой или салфеткой перед началом путешествия». Продовження руху з брудними дзеркалами небезпечно знижує огляд; нахил дзеркал вперед не очищує їх."}, {"num": 578, "text": "Когда водитель поворачивает налево, на каких зеркалах он должен концентрироваться?", "topic": "Загальні правила та поведінка на дорозі", "options": ["Внутреннее и наружное правое зеркало.", "Внутреннее и наружное левое зеркало.", "Правое наружное зеркало.", "Внутреннее зеркало."], "correct": 1, "expl": "Повертаючи ліворуч, водій має зосередитися на внутрішньому дзеркалі та лівому зовнішньому, щоб побачити пішоходів чи транспорт саме з того боку, куди він повертає.", "explSpecific": "Правильно — «Внутреннее и наружное левое зеркало». Праве зовнішнє дзеркало показує протилежний бік; використання лише одного дзеркала залишає сліпу зону саме з боку повороту."}, {"num": 579, "text": "Какое влияние может оказать сырая погода на наружные зеркала автомобиля?", "topic": "Загальні правила та поведінка на дорозі", "options": ["Капли воды могут сделать отраженный объект ближе, чем он есть на самом деле.", "Вода может вызвать короткое замыкание в зеркалах с электроподогревом.", "Капли воды могут затенить отражение.", "Капли воды помогают содержать их в чистоте."], "correct": 2, "expl": "Краплі дощу на дзеркалах спотворюють і затемнюють відображення, ускладнюючи чітке бачення транспорту позаду чи збоку.", "explSpecific": "Правильно — «Капли воды могут затенить отражение». Твердження, що краплі роблять об'єкт ближчим чи допомагають чистоті дзеркал, — вигадані ефекти."}, {"num": 580, "text": "Что обычно означает сизый дым из выхлопной трубы автомобиля?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Перегрев двигателя.", "Износ каталитического конвертера.", "Горение масла в двигателе.", "Необходимость замены воздушного фильтра."], "correct": 2, "expl": "Сизий (голубувато-сірий) дим із вихлопної труби — характерна ознака того, що моторне масло потрапляє в камеру згоряння і згоряє разом з паливом.", "explSpecific": "Правильно — «Горение масла в двигателе». Перегрів двигуна зазвичай проявляється парою з-під капота, а не сизим димом з вихлопу; знос каталізатора чи забруднений повітряний фільтр мають інші, не пов'язані з кольором диму прояви."}, {"num": 581, "text": "К чему ведет износ выхлопной трубы?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Уменьшение фильтрации паров, и увеличение шума двигателя.", "Перегрев двигателя.", "Повышение топливной эффективности, поскольку пары выходят быстрее.", "Затруднение переключения передач."], "correct": 0, "expl": "Зношена вихлопна труба втрачає здатність гасити звук вихлопу і фільтрувати гарячі гази, тому основні наслідки — гучніший шум і гірша фільтрація.", "explSpecific": "Правильно — «Уменьшение фильтрации паров, и увеличение шума двигателя». Перегрів двигуна не є прямим наслідком зносу вихлопної труби; «підвищення ефективності» і «ускладнення перемикання передач» — вигадані, технічно необґрунтовані твердження."}, {"num": 582, "text": "К чему ведет износ выхлопной системы?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Улучшение расхода топлива автомобиля.", "Повышение уровня шума и загрязнения от автомобиля.", "Снижение шума автомобиля.", "Повышение износа двигателя автомобиля."], "correct": 1, "expl": "Пошкоджена чи зношена вихлопна система гірше глушить звук роботи двигуна і гірше очищує вихлопні гази, тому шум і забруднення від автомобіля зростають.", "explSpecific": "Правильно — «Повышение уровня шума и загрязнения от автомобиля». Покращення витрати палива чи зниження шуму прямо суперечать фізичному ефекту зносу; підвищений знос двигуна не є прямим наслідком саме вихлопної системи."}, {"num": 583, "text": "Какова цель каталитического нейтрализатора?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Ограничить уровень шума выхлопных газов только на автомобилях с дизельным двигателем.", "Снизить вредные выбросы выхлопных газов.", "Позволить восстановить выхлопную систему.", "Ограничить уровень шума выхлопной системы только на автомобилях с бензиновым двигателем."], "correct": 1, "expl": "Каталітичний нейтралізатор призначений очищувати вихлопні гази від шкідливих речовин перед їх викидом в атмосферу, знижуючи забруднення довкілля.", "explSpecific": "Правильно — «Снизить вредные выбросы выхлопных газов». Обмеження шуму саме для дизельних чи бензинових двигунів окремо — вигадане звуження; «відновити вихлопну систему» не є функцією каталізатора."}, {"num": 584, "text": "На что указывает индекс скорости шины?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Максимальная скорость, на которую рассчитана шина.", "Минимальная скорость, на которую рассчитана шина.", "Максимальная скорость, на которой автомобиль может совершить обгон.", "Максимальная скорость движения автомобиля."], "correct": 0, "expl": "Індекс швидкості на боковині шини — це буквений код, що визначає максимальну швидкість, на яку розрахована саме ця шина за нормальних умов експлуатації.", "explSpecific": "Правильно — «Максимальная скорость, на которую рассчитана шина». Мінімальна швидкість шини — поняття, якого не існує в цьому контексті; максимальна швидкість обгону чи руху автомобіля в цілому залежить від правил дороги, а не від маркування шини."}, {"num": 585, "text": "Зачем заменять клапан при установке бескамерной шины?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Для обеспечения правильной регулировки колес.", "Чтобы избежать спуска шины.", "Для обеспечения правильной балансировки колеса.", "Для обеспечения постоянной затяжки гаек крепления колеса."], "correct": 1, "expl": "При встановленні безкамерної шини вентиль (клапан) є одноразовим ущільнювальним елементом — його заміна запобігає повільному витоку повітря через старий, зношений гумовий ущільнювач.", "explSpecific": "Правильно — «Чтобы избежать спуска шины». Регулювання колінь чи балансування колеса — це geть інші процедури, не пов'язані з заміною вентиля; постійна затяжка гайок кріплення також не залежить від стану клапана."}, {"num": 586, "text": "После замены колеса на транспортном средстве, что из следующего следует проверить после прохождения короткого расстояния?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Воздушный клапан шины.", "Зазор тормозной колодки.", "Затяжку гайки крепления колеса.", "Глубину протектора шины."], "correct": 2, "expl": "Після заміни колеса й проїзду невеликої відстані гайки кріплення можуть трохи послабитися через усадку деталей, тому їхню затяжку обов'язково перевіряють повторно.", "explSpecific": "Правильно — «Затяжку гайки крепления колеса». Повітряний клапан, зазор колодок чи глибина протектора не змінюються від самого факту заміни колеса й короткої поїздки."}, {"num": 587, "text": "В общем, как часто водитель должен проверять давление в шинах автомобиля?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Ежемесячно.", "Раз в пол года.", "Ежегодно.", "Регулярно."], "correct": 3, "expl": "Тиск у шинах природно змінюється з температурою та поступово падає через природну дифузію повітря, тому перевіряти його варто регулярно, а не лише в межах формального інтервалу обслуговування.", "explSpecific": "Правильно — «Регулярно». Щомісячна, піврічна чи щорічна перевірка — надто рідкісні фіксовані інтервали, які не встигають вчасно виявити поступову втрату тиску між ними."}, {"num": 588, "text": "Какова основная причина поддержания правильного давления в шинах?", "topic": "Технічні несправності та аварійні ситуації", "options": ["Чтобы помочь поддерживать правильный дорожный просвет.", "Чтобы предотвратить уклон автомобиля влево.", "Чтобы снизить износ двигателя.", "Помочь обеспечить оптимальное сцепление с дорогой."], "correct": 3, "expl": "Правильний тиск у шинах забезпечує оптимальну площу контакту протектора з дорогою, а отже — найкраще можливе зчеплення.", "explSpecific": "Правильно — «Помочь обеспечить оптимальное сцепление с дорогой». Дорожній просвіт, знос двигуна чи ухил автомобіля вбік не є головною причиною підтримання правильного тиску в шинах."}]);
